-- ZShare's settings, from the lobby and from a match: the BOIII and T7x
-- builds.
--
-- Generated by tools/mk_t7_uiscripts.py from the Workshop build's
-- ui/zshare/zsharesettings.lua, with only its requires changed -- a ui_script
-- asks for a sibling by bare name. Never edit by hand: an edit here would be
-- undone by the next build, and the two menus would drift apart.
--
-- Dropped in as <client>/ui_scripts/zshare/__init__.lua, which the client
-- runs inside the game's own LUI. The lobby button and the save file are
-- still the frontend's, on the same test the clients' own ui_scripts open on.
--
-- The one thing that is not the same here: the page's background. An image
-- can only arrive in a fastfile and there is none on this route, so the page
-- draws a half-transparent black panel instead. It decides that when it runs
-- -- this is the same file, not a second page.
--
-- A setting saved here goes into the offline zombies loadouts, as it does on
-- the Workshop build -- but with no mod loaded that is the player's own file
-- rather than a mod's copy. Zombies has no create-a-class, so nothing in a
-- zombies game reads it.

require( "zsharesettingsdata" )

local Z = CoD.ZShareSettings

-- The shared component registry, created here rather than beside the rest of
-- its own block further down: everything in this file that reads it has to be
-- able to see this local, and a function defined above the declaration reads
-- a nil global of the same name. Whichever Z mod loads first builds it.
CoD.ZBundleSettings = CoD.ZBundleSettings or {}
local B = CoD.ZBundleSettings
Z.saved = {}
Z.dirty = false
-- Whether the save file has actually been read. Nothing is written over a
-- file nobody has read: in a match the loadouts buffer can be out of reach,
-- and a write from there would put an empty set over everything saved.
Z.loaded = false
-- Every row that is saved, in the order the generator laid them out -- which
-- is the order their places in the save file were worked out from, so this
-- list and that layout cannot disagree.
Z.AllRows = {}
for _, page in ipairs( Z.Pages ) do
	for _, row in ipairs( page.rows ) do
		table.insert( Z.AllRows, row )
	end
end
-- Saved like the rest and on no page: zs_enabled, which the shared menu
-- shows on the bundle's MODS page rather than as a setting of ZShare's own.
-- Black Ops III keeps no dvar once it closes, so a mod switched off has to
-- be written down or it is back the next time the game starts. Last, so a
-- setting added to a page cannot move it out from under somebody who had
-- switched ZShare off.
for _, row in ipairs( Z.Hidden or {} ) do
	table.insert( Z.AllRows, row )
end

-- ------------------------------------------------------------------------
-- Words
-- ------------------------------------------------------------------------

-- What the page calls things. The Workshop build links ZShare's own strings
-- in all twelve languages the game ships and a zombies match has them loaded;
-- the frontend and the loose-script clients do not, and Engine.Localize hands
-- back the key it was given when there is no such string -- so the English
-- the table was written from is the fallback, and nobody ever reads a key.
--
-- That route could never serve this menu, and it was tried: a key only resolves where the fastfile
-- carrying it is loaded, ZShare's strings ride in zm_mod which is a match's zone, and this menu
-- opens in the frontend -- with no fastfile at all on the loose clients. A key that does not
-- resolve is drawn as the key, which is exactly what the menu showed in game: rows of
-- ZSHARE_MENU_DEFAULT under a ZSHARE_MENU_TITLE.
--
-- **Z.Text is no longer defined here.** zsharesettingsdata.lua defines it, from the catalog
-- embedded in that file, and this file requires that one at the top -- so a definition here would
-- run second and silently shadow the catalog with "return english". A translation route that does
-- not depend on a fastfile being loaded is the whole point of the shared localization core; see the
-- ZS_LOCALE block in the generated data. The 64 call sites below are unchanged and now go through
-- the catalog, falling back to the English they already pass in.
--
-- The lines players read during a match -- every zs_say, zs_say_all and zs_show -- are keyed as
-- they always were, and those do resolve, because a match has zm_mod loaded.

-- A word of the game's own, which every route has in every language.
Z.Stock = function ( key, english )
	local ok, text = pcall( Engine.Localize, key )
	if not ok or type( text ) ~= "string" or text == "" or text == key then
		return english
	end
	local upper, out = pcall( Engine.ToUpper, text )
	if upper and type( out ) == "string" and out ~= "" then
		return out
	end
	return text
end

-- The shared shell's own words. They are made by whichever Z mod loaded first and compared as
-- literals (row.boundary == "READ ONLY"), so they are translated here, where ZShare draws them, and
-- never where they are made: a copy of the shell that translated its own words would read
-- differently by load order, and its comparisons would stop matching. A closed list, looked up by
-- the literal - the way the boundary vocabulary is keyed in tools/mk_locale.py - and anything not
-- on it is drawn as it came. A brand (ZSHARE, ZBUNDLE SETTINGS, another owner's label) is a name
-- and not a word, and is not on it.
Z.Words = Z.Words or {}
Z.Word = function ( key, english )
	Z.Words[english] = key
end
Z.Word( "ui.tab_mods", "MODS" )
Z.Word( "ui.tab_mods_hint", "Switch each mod on this screen on or off." )
Z.Word( "ui.tab_changed", "CHANGED" )
Z.Word( "ui.tab_changed_hint", "Settings changed from their defaults, across every mod on this screen." )
Z.Word( "ui.mod_switch_hint", "Switch this mod on or off." )
Z.Word( "ui.component_hint", "Trading weapons with a teammate, giving points, and sharing or paying for the box, the Pack-a-Punch and the perk machines." )
Z.Word( "ui.next_match", "NEXT MATCH" )
Z.Word( "ui.read_only", "READ ONLY" )
Z.Word( "ui.scope_host", "HOST / SHARED" )
Z.Word( "ui.on", "ON" )
Z.Word( "ui.off", "OFF" )
Z.Word( "ui.host_value_unavailable", "HOST VALUE UNAVAILABLE" )
Z.Word( "ui.host_unknown_reason", "Host status unknown; this host-controlled setting is locked." )
Z.Word( "ui.host_only_reason", "Only the host can change this setting. The host's current value is unavailable here." )

Z.Word( "ui.override_unavailable", "Override unavailable" )

Z.Shell = function ( text )
	local key = type( text ) == "string" and Z.Words[text] or nil
	if key ~= nil then
		return Z.Text( key, text )
	end
	-- The one shell sentence with a value in it: a locked row's reason when its owner gave none.
	-- ZShare locks nothing, so this is somebody else's row drawn here.
	local value = type( text ) == "string" and string.match( text, "^Locked to (.+)$" ) or nil
	if value ~= nil then
		return Z.Format( "ui.locked_to", "Locked to {value}", { value = value } )
	end
	return text
end

-- Whose words a row's are. A generated row says so itself (localizationOwner), which is what lets
-- any renderer find the owner without being handed the tab; a CHANGED copy names its source mod in
-- sourceOwner. Both are the shared kit's own field names, read in the kit's own order.
Z.OwnerOf = function ( row )
	if type( row ) ~= "table" then
		return nil
	end
	return row.sourceOwner or row.localizationOwner
end

-- Another mod's words, through that mod's own localizer. Every Z mod registers one as
-- CoD.ZBundleSettings.Localizers.<owner> from its own generated data, so it is there whichever
-- renderer is drawing - and this renderer drawing ZPause's row asks ZPause, never ZShare's catalog.
-- Nil when there is nobody to ask or nothing came back, so the caller falls through to the shell.
Z.Foreign = function ( english, owner, row, tab )
	if type( owner ) ~= "string" or owner == Z.Owner or owner == "zbundle" then
		return nil
	end
	local registry = CoD.ZBundleSettings
	local providers = type( registry ) == "table" and registry.Localizers or nil
	local provider = type( providers ) == "table" and providers[owner] or nil
	if type( provider ) ~= "table" or provider.version ~= 1 or type( provider.text ) ~= "function" then
		return nil
	end
	local ok, text = pcall( provider.text, english, { owner = owner, row = row, tab = tab } )
	if ok and type( text ) == "string" and text ~= "" and text ~= english then
		return text
	end
	return nil
end

-- A line the generator gave a key as well as its English. **The key is used only while the English
-- is still the English it was made from** - see Z.Source - so a row somebody copied and re-worded
-- draws its own words rather than the source row's translated ones. Another mod's line goes to that
-- mod's localizer first; a line with no key, or one that has stopped fitting it, may still be one
-- of the shell's words.
Z.Keyed = function ( key, english, fallback, owner, row, tab )
	if type( english ) ~= "string" or english == "" then
		english = fallback or ""
	end
	local foreign = Z.Foreign( english, owner, row, tab )
	if foreign ~= nil then
		return foreign
	end
	if type( key ) == "string" and key ~= "" and Z.Source( key ) == english then
		return Z.Text( key, english )
	end
	return Z.Shell( english )
end

-- A pause-menu action's label, in the words of the mod that registered it. B.ActionLabel is the
-- registry's and translates nothing, so another mod's action drew in English on this renderer
-- until it asked that mod; anything nobody translates may still be one of the shell's words.
Z.ActionWords = function ( action, controller )
	local english = CoD.ZBundleSettings.ActionLabel( action, controller )
	if type( action ) ~= "table" or type( english ) ~= "string" then
		return english
	end
	local foreign = Z.Foreign( english, action.owner, action )
	if foreign ~= nil then
		return foreign
	end
	return Z.Shell( english )
end

-- Every line a row carries is drawn through one of these three. Until 11 October T7 drew
-- row.label, row.hint and row.labels[i] as they were stored, so its catalog translated the tabs
-- and the chrome and left every setting name, description and choice in English - while the
-- release check counted the keys the rows CARRY as keys the menu ASKS for.
Z.RowLabel = function ( row, fallback )
	return Z.Keyed( row.labelKey, row.label, fallback or row.dvar or "", Z.OwnerOf( row ), row )
end

Z.RowHint = function ( row )
	return Z.Keyed( row.hintKey, row.hint, "", Z.OwnerOf( row ), row )
end

-- By identity, never by position. A copy that lists one current value keeps the source row's
-- whole list of choice keys, so its first key names the source row's FIRST choice. So the key is
-- the one of this row's whose English is the label being drawn.
Z.ChoiceLabel = function ( row, index, fallback )
	local english = ( row.labels or {} )[index]
	if type( english ) ~= "string" or english == "" then
		english = fallback or ""
	end
	local foreign = Z.Foreign( english, Z.OwnerOf( row ), row )
	if foreign ~= nil then
		return foreign
	end
	for _, key in ipairs( row.choiceKeys or {} ) do
		if Z.Source( key ) == english then
			return Z.Text( key, english )
		end
	end
	return Z.Shell( english )
end

-- What a row's state is called on screen. The state itself is an internal word that other code
-- compares, so it is never translated where it is kept - only here, where it is drawn.
Z.StateText = function ( state )
	if state == "OVERRIDDEN" then
		return Z.Text( "ui.overridden", "OVERRIDDEN" )
	end
	if state == "DISABLED" then
		return Z.Text( "ui.disabled", "DISABLED" )
	end
	if state == "HOST" then
		return Z.Text( "ui.host_controlled", "HOST CONTROLLED" )
	end
	return tostring( state or "" )
end

-- ------------------------------------------------------------------------
-- Settings
-- ------------------------------------------------------------------------

-- Whether the value a dvar holds is the one a choice stands for, numbers
-- compared as numbers: "0.30" is 0.3.
Z.Same = function ( a, b )
	local na = tonumber( a )
	local nb = tonumber( b )
	if na ~= nil and nb ~= nil then
		return na == nb
	end
	return a == b
end

-- Whether a setting is still at its default. Empty is the obvious case, but
-- the script writes every default into its dvar as a match loads, so after
-- one has been played every setting nobody touched holds its default.
Z.IsDefault = function ( current, row )
	return current == "" or Z.Same( current, row.default )
end

Z.Get = function ( dvar )
	local ok, value = pcall( Engine.DvarString, nil, dvar )
	if ok and type( value ) == "string" then
		return value
	end
	return ""
end

-- Engine.SetDvar is what the game's own settings pages use. Where that did
-- not take, the console's set does it: set is how a dvar that nothing has
-- made yet comes to exist.
Z.Set = function ( controller, dvar, value, row )
	-- An older shell sends an empty value to mean DEFAULT. What gets written
	-- is the row's own declared default instead: an empty dvar is whatever
	-- the engine registered the name with, which is not always what the menu
	-- calls DEFAULT, and the row then reads as changed while its selector
	-- says otherwise.
	if value == "" and row ~= nil and row.default ~= nil then
		value = row.default
	end
	pcall( Engine.SetDvar, dvar, value )
	if Z.Get( dvar ) ~= value then
		-- A quote inside the value would close the one this opens and
		-- leave the console a malformed command. Nothing the pages offer
		-- has one; a value typed into the console might.
		Engine.Exec( controller, "set " .. dvar .. " \"" .. string.gsub( value, "\"", "" ) .. "\"" )
	end
end

-- The label a row's own default is drawn under, so the page can say what
-- DEFAULT currently means.
Z.DefaultLabel = function ( row )
	for index, value in ipairs( row.values or {} ) do
		if Z.Same( value, row.default ) then
			return Z.ChoiceLabel( row, index, value )
		end
	end
	return row.default or ""
end

-- Asked through here rather than straight off the registry, because the
-- registry may be another mod's copy of the block above and the two namings
-- are not the same shape. Either one answers ( value, locked ) from this.
Z.Override = function ( row, tab, controller )
	if type( B.RowOverride ) == "function" then
		return B.RowOverride( row, tab, controller )
	end
	if type( B.RowForced ) == "function" then
		local locked, value = B.RowForced( row, tab, controller )
		return value, locked
	end
	return nil, false
end

Z.Unavailable = function ( row, tab, controller )
	if type( B.RowUnavailable ) == "function" then
		return B.RowUnavailable( row, tab, controller )
	end
	local _, locked = Z.Override( row, tab, controller )
	return locked or not B.RowEnabled( row, tab, controller )
end

-- And the reason, as a string whatever answers it. ZPause's copy returns nil
-- where this one returns the row's own hint, and a nil in a concatenation is
-- not a blank line -- it is the whole page failing to build.
Z.Reason = function ( row, tab, controller )
	local text = nil
	if type( B.RowReason ) == "function" then
		text = B.RowReason( row, tab, controller )
	end
	if text == nil or text == "" then
		local _, locked = Z.Override( row, tab, controller )
		if locked then
			text = row.overrideReason
		elseif not B.RowEnabled( row, tab, controller ) then
			text = row.disabledReason
		end
		if type( text ) == "function" then
			local ok, value = pcall( text, controller or 0, row, tab )
			text = ok and value or nil
		end
		if text == nil or text == false then
			text = Z.RowHint( row )
		end
	end
	-- Drawn here, so translated here. A copy of the shell - this one included - may have answered
	-- with the row's own English hint, which is put back through the row's keys; anything else it
	-- said is either one of the shell's own sentences or somebody else's words.
	if text == row.hint then
		return Z.RowHint( row )
	end
	return Z.Shell( tostring( text ) )
end

-- What a value reads as. An empty setting is the inherited default, and a
-- row that cannot be written says what it currently *is*: a blank there is
-- the one answer that tells a player nothing.
Z.ValueLabel = function ( row, value )
	if value == nil or value == "" or Z.Same( value, row.default ) then
		local label = Z.DefaultLabel( row )
		-- A row with no default of its own -- somebody else's -- would
		-- otherwise read as nothing at all.
		if label == nil or label == "" then
			return Z.Text( "ui.default", "DEFAULT" )
		end
		return label
	end
	for index, choice in ipairs( row.values or {} ) do
		if Z.Same( value, choice ) then
			return Z.ChoiceLabel( row, index, choice )
		end
	end
	return string.upper( tostring( value ) )
end

-- What the details panel says a change waits for, and who it is for. Both
-- come from the row -- tools/mk_t7_lobby.py has the table -- because the
-- script is what decides them and a guess made here from a setting's name
-- would be wrong the first time one moved.
Z.Boundary = function ( row )
	return Z.Keyed( row.boundaryKey, row.boundary, "" )
end

Z.Scope = function ( row )
	return Z.Keyed( row.scopeKey, row.scope, Z.Text( "ui.scope_host", "HOST / SHARED" ) )
end

-- Whether a button may be pressed. **Not `RowWritable`**, which is false for
-- every button -- a button has no values to write -- so it says nothing about
-- activation. It is the full unavailability answer, locks included, plus the
-- read-only names under all four spellings: an informational row that happens
-- to carry an action is still informational.
Z.ButtonAvailable = function ( row, tab, controller )
	return not Z.Unavailable( row, tab, controller ) and row.readOnly ~= true
		and row.ztReadOnly ~= true and row.writable ~= false and row.editable ~= false
		and row.boundary ~= "READ ONLY"
end

-- One press, on the row that was actually pressed.
--
-- A click arrives from the control inside the row, so the row is found by
-- walking up to the grid and reading its own index. **A control that is not
-- in the grid any more gives up rather than falling back to whatever has
-- focus** -- a stale click that activated the previously focused row is how
-- a press on one mod's row runs another mod's destructive action.
--
-- Availability is asked again here and not trusted from render time: a lock
-- can arrive between the page being drawn and the button being pressed.
Z.ButtonRowAt = function ( menu, controller, control )
	if menu == nil or menu.Options == nil then
		return false
	end
	local index = nil
	if control ~= nil then
		local item = control
		while item ~= nil and item ~= menu.Options do
			local parent = type( item.getParent ) == "function" and item:getParent() or nil
			if parent == menu.Options then
				index = item.gridInfoTable ~= nil and item.gridInfoTable.zeroBasedIndex or nil
				break
			end
			item = parent
		end
		if index == nil then
			return false
		end
	else
		-- The row that has focus now, and nothing else: an old list
		-- selection is not a press on anything, and firing it ran an action
		-- the player was no longer on.
		local active = menu.Options.activeWidget
		if active == nil or active.gridInfoTable == nil or active.gridInfoTable.zeroBasedIndex == nil then
			return false
		end
		index = active.gridInfoTable.zeroBasedIndex
	end
	local row = ( menu.zsRows or {} )[index + 1]
	if row == nil or row.kind ~= "button" then
		return false
	end
	local tab = menu.zsTab
	if Z.ButtonAvailable( row, tab, controller ) and type( row.action ) == "function" then
		-- The live menu goes with it: an action that has to close or rebuild
		-- the screen it was pressed from has no other way to reach it.
		pcall( row.action, controller, menu, row, tab )
	end
	return true
end

-- A report row -- somebody else's compatibility tab, say -- says what it is
-- and cannot be changed, so the bulk actions step over it.
-- Kept as the name the rest of this file uses, and nothing more: the answer
-- is the shared registry's, so a bundle cannot disagree with itself about
-- which rows are informational. The tab matters -- a CHANGED or report role
-- makes every row in it inert -- so it is passed wherever it is known.
Z.Writable = function ( row, tab, controller )
	return B.RowWritable( row, tab, controller )
end

-- ------------------------------------------------------------------------
-- Saving
--
-- Black Ops III keeps no dvar once it closes, so a choice made here has to
-- be written down. A mod keeps save files of its own -- players/mods/<folder>/
-- for a local mod, players/311210/<item>/ for a Workshop item -- and what
-- ZShare writes into is the offline zombies loadouts: zombies has no
-- create-a-class, so nothing in a zombies game reads any of it.
--
-- **Whose fields these are matters more than how they are packed.** Three of
-- Xep's mods write into this one file, and a bundle has all three of them in
-- it at once:
--
--     ZPause   the class names, customClassName[0..31], as text
--     ZTweaks  primaryattachment3 through 8, as numbers
--     ZShare   primaryattachment1 and primaryattachment2, as numbers
--
-- Nothing here reads or writes outside those two fields. Picking the two
-- numeric slots ZTweaks left alone rather than inventing a storage of its
-- own is deliberate: the numeric loadout fields are the part of this file
-- that is known to hold a value and give it back, and a third mod guessing
-- at some other corner of the save is a third way to find out it does not.
--
-- A setting is a number in one of those fields. Several share a field, each
-- with a place value of its own -- the generator gives every row a slot, a
-- factor and a radix, so a setting added later gets a place of its own and
-- leaves the ones already saved where they are. 0 is "not saved", which is
-- what DEFAULT means, so a row at its default takes no room and follows
-- whatever default the build carries.
--
-- customclass[0].primaryattachment1 is the marker rather than a setting: it
-- says a ZShare record is there at all, so "saved nothing" and "never saved"
-- are told apart, and nothing is written over a file that has not been read.
-- ------------------------------------------------------------------------

Z.STORAGE = Enum.StorageFileType.STORAGE_ZM_LOADOUTS_OFFLINE

-- The number the marker holds. ZTweaks writes 100 and 101 in its own marker
-- field; this is a different field, and a different number besides, so a
-- value found here that is not this one is not ZShare's and is left alone.
Z.FORMAT = 200

-- **The marker field is one of the game's own.** `customclass[0]`'s first
-- attachment slot holds a real attachment index for anybody who has ever set
-- one on that offline zombies class, and that number is the game's data, not
-- another mod's record: ZShare has always claimed this field and writing it
-- is the whole design. Only a value in the space the Z mods mark with is a
-- record worth refusing to overwrite -- ZTweaks writes 100 and 101, ZShare
-- 200, ZStats 300, all three digits and all clear of any attachment index.
--
-- Reading a stock value as a foreign record is what 1.3.26.d did, and it
-- left the page saying NOT SAVED to a player whose only crime was having
-- configured a loadout.
Z.MARKER_MIN = 100

-- What the save is doing, in one word, so a failure is something the page can
-- say rather than something a player finds out two sessions later. The names
-- are the shared ABI handoff's: read_pending, unknown_format,
-- capacity_exhausted, write_rejected, verify_mismatch, committed.
--
-- read_pending to begin with, because that is the truth before the frontend
-- has handed the save files over, and nothing may be written until a read has
-- said which record is there.
Z.Status = "read_pending"

Z.LoadoutRoot = function ( controller )
	local root = nil
	pcall( function ()
		root = Engine.StorageGetBuffer( controller, Z.STORAGE ).cacLoadouts
	end )
	return root
end

-- The marker. customclass[0]'s first attachment slot, which is the one field
-- ZShare never gives to a setting.
Z.MarkerField = function ( controller )
	local root = Z.LoadoutRoot( controller )
	if root == nil then
		return nil
	end
	local field = nil
	pcall( function ()
		field = root.customclass[0].primaryattachment1
	end )
	return field
end

-- A row's field: slots 1 to 10 are each loadout's second attachment slot,
-- 11 to 19 the first attachment slot of every loadout but the marker's. The
-- generator never hands out a slot past 19, and says so if the settings ever
-- need one.
Z.ValueField = function ( controller, row )
	local root = Z.LoadoutRoot( controller )
	if root == nil or row.storageSlot == nil then
		return nil
	end
	local field = nil
	pcall( function ()
		if row.storageSlot <= 10 then
			field = root.customclass[row.storageSlot - 1].primaryattachment2
		else
			field = root.customclass[row.storageSlot - 10].primaryattachment1
		end
	end )
	return field
end

Z.ReadMarker = function ( controller )
	local field = Z.MarkerField( controller )
	if field == nil then
		return nil
	end
	local value = nil
	pcall( function ()
		value = tonumber( field:get() )
	end )
	return value
end

-- The rows sharing each field, worked out once: a field is written whole, so
-- every setting in it has to be in hand at the same time. And what the field
-- can hold, which is the product of its settings' radices -- the one number
-- that says whether what is in there was written by a build like this one.
Z.RowsBySlot = {}
Z.Slots = {}
Z.SlotCapacity = {}
for _, row in ipairs( Z.AllRows ) do
	if row.storageSlot ~= nil then
		if Z.RowsBySlot[row.storageSlot] == nil then
			Z.RowsBySlot[row.storageSlot] = {}
			Z.SlotCapacity[row.storageSlot] = 1
			table.insert( Z.Slots, row.storageSlot )
		end
		table.insert( Z.RowsBySlot[row.storageSlot], row )
		Z.SlotCapacity[row.storageSlot] = Z.SlotCapacity[row.storageSlot] * row.storageRadix
	end
end
table.sort( Z.Slots )

-- dvar -> value for every setting saved away from its default, and which of
-- four things the file turned out to be. "Could it be read" is not one
-- question but three, and the differences decide whether anything may be
-- written:
--
--   unreachable  the storage is not there -- which is what a match looks
--                like. Nothing is known, so nothing may be written.
--   empty        read perfectly well, and no ZShare record in it. This is
--                what the first save writes into.
--   known        a ZShare record this build understands.
--   unknown      something else is in ZShare's marker field: a record from a
--                later build, or another mod's. It is left exactly as it is
--                -- a write would replace a record this build cannot read
--                with one it can, which is the one unrecoverable outcome
--                here -- and the page says so.
--   invalid      the marker is ZShare's and a field is not: not a whole
--                number, or past what that field was sized to hold. Left
--                alone for the same reason as an unknown one, since
--                decoding a guess and writing it back is how a half-read
--                record becomes the record.
Z.Read = function ( controller )
	local saved = {}
	if Z.MarkerField( controller ) == nil then
		return saved, "unreachable"
	end
	local marker = Z.ReadMarker( controller )
	if marker == nil or marker < Z.MARKER_MIN then
		-- Nothing, or the game's own value in a field ZShare owns.
		return saved, "empty"
	end
	if marker ~= Z.FORMAT then
		return saved, "unknown"
	end
	for _, slot in ipairs( Z.Slots ) do
		local field = Z.ValueField( controller, Z.RowsBySlot[slot][1] )
		local stored = 0
		if field ~= nil then
			local raw = nil
			pcall( function ()
				raw = tonumber( field:get() )
			end )
			-- A field a build like this one wrote holds a whole number inside
			-- the capacity the generator sized it for. Anything else is not a
			-- ZShare record whatever the marker says.
			if raw ~= nil then
				if raw < 0 or raw ~= math.floor( raw )
					or raw >= ( Z.SlotCapacity[slot] or 0 ) then
					return {}, "invalid"
				end
				stored = raw
			end
		end
		for _, row in ipairs( Z.RowsBySlot[slot] ) do
			local code = math.floor( stored / row.storageFactor ) % row.storageRadix
			-- 0 is DEFAULT, and so is anything past the end of the list --
			-- which is what an older build's record looks like once a value
			-- has been taken out of a row.
			if code >= 1 and row.values[code] ~= nil then
				saved[row.dvar] = row.values[code]
			end
		end
	end
	return saved, "known"
end

-- Every field encoded, checked, set and read back before the file is asked
-- to commit, and the reason kept on Z.Status wherever it stops. Nothing here
-- clears the dirty flag: Z.Flush does that, and only on a true.
Z.Write = function ( controller )
	if not Z.loaded then
		return false
	end
	-- Asked again here and not only at load: between the read and this, the
	-- file can have been written by something else -- a later build of
	-- ZShare, another mod reaching into the same field. Having read it once
	-- is not standing permission to write over whatever is there now.
	local marker = Z.ReadMarker( controller )
	if marker ~= nil and marker >= Z.MARKER_MIN and marker ~= Z.FORMAT then
		Z.Status = "unknown_format"
		return false
	end
	for _, slot in ipairs( Z.Slots ) do
		local field = Z.ValueField( controller, Z.RowsBySlot[slot][1] )
		if field == nil then
			return false
		end
		local stored = 0
		for _, row in ipairs( Z.RowsBySlot[slot] ) do
			local code = 0
			local value = Z.saved[row.dvar]
			if value ~= nil and not Z.IsDefault( value, row ) then
				for index, known in ipairs( row.values ) do
					if Z.Same( known, value ) then
						code = index
						break
					end
				end
			end
			if code >= row.storageRadix then
				-- A value that does not fit the place it was given. The
				-- generator sizes every field, so this is a build error
				-- rather than something a player can cause -- and it still
				-- stops the write instead of saving a wrong number.
				Z.Status = "capacity_exhausted"
				return false
			end
			stored = stored + code * row.storageFactor
		end
		if not pcall( field.set, field, stored ) then
			Z.Status = "write_rejected"
			return false
		end
		-- Read back rather than assumed: a field that silently refuses the
		-- number would leave the page saying a setting is kept when it is not.
		local verified = nil
		pcall( function ()
			verified = tonumber( field:get() )
		end )
		if verified ~= stored then
			Z.Status = "verify_mismatch"
			return false
		end
	end
	local markerField = Z.MarkerField( controller )
	if markerField == nil or not pcall( markerField.set, markerField, Z.FORMAT ) then
		Z.Status = "write_rejected"
		return false
	end
	-- The commit's own answer, which used to be dropped. An explicit false is
	-- the game saying it did not take the file, and taking that for success
	-- clears the dirty flag and loses the change -- the keeper has nothing
	-- left to retry with.
	local ok, written = pcall( Engine.StorageWrite, controller, Z.STORAGE )
	if not ok or written == false then
		Z.Status = "write_rejected"
		return false
	end
	-- The fields are set and the file is in. Whether it survives the process
	-- is the one thing nothing here can see.
	Z.Status = "committed"
	return true
end

-- Saved when a page closes, not on every press. The flag comes down only
-- once the write is in: Z.Write returns false when there is no field to
-- write to, and it is called through pcall because it can throw, so clearing
-- first threw the change away on the one pass that needed keeping.
Z.Flush = function ( controller )
	if Z.dirty then
		local ok, written = pcall( Z.Write, controller )
		if ok and written == true then
			Z.dirty = false
		end
	end
end

-- What the page says about the save, and nothing when there is nothing to
-- say. A change takes effect in the game the moment it is made, which is the
-- half a player can see; whether it was written down is the half they cannot,
-- and a failure nobody mentions is a setting they believe is kept.
--
-- The ordinary wait between a press and the flush is not reported: it is
-- seconds long and always ends, and a line that is on screen for every press
-- is one nobody reads by the third.
Z.StatusText = function ()
	if Z.Status == "unknown_format" then
		return Z.Text( "ui.save_foreign", "NOT SAVED: another record is in ZShare's save fields" )
	end
	if Z.Status == "invalid_record" then
		return Z.Text( "ui.save_invalid", "NOT SAVED: the saved record cannot be read" )
	end
	if Z.Status == "capacity_exhausted" then
		return Z.Text( "ui.save_range", "NOT SAVED: a value does not fit its save field" )
	end
	if Z.Status == "verify_mismatch" then
		return Z.Text( "ui.save_mismatch", "NOT SAVED: the save file did not keep the value" )
	end
	if Z.Status == "write_rejected" then
		return Z.Text( "ui.save_refused", "NOT SAVED: the game refused the save" )
	end
	if Z.dirty and not Z.loaded then
		return Z.Text( "ui.save_waiting", "NOT SAVED YET: waiting for the save file" )
	end
	return nil
end

-- The category's own line, and the save's where the save has one.
Z.SubtitleText = function ( tab )
	local hint = Z.TabHint( tab ) or ""
	local status = Z.StatusText()
	if status == nil then
		return hint
	end
	if hint == "" then
		return status
	end
	return hint .. "  -  " .. status
end

-- Once a game: what was saved goes back into the dvars the first time the
-- frontend starts with this mod loaded, and not again after a match, so a
-- change the host made from the pause menu lasts until the game closes, the
-- same as one typed into the console.
--
-- A file with no ZShare record in it still counts as read: there is nothing
-- saved, which is a different thing from not knowing, and it is what lets
-- the first save happen at all.
Z.Startup = function ( controller )
	local saved, state = Z.Read( controller )
	-- A record this build understands, or the room to write the first one.
	-- Neither of the other two answers permits a restore or a write.
	local readable = state == "known" or state == "empty"
	if state == "invalid" then
		Z.Status = "invalid_record"
	elseif state == "unknown" then
		Z.Status = "unknown_format"
	elseif readable and ( Z.Status == "read_pending" or Z.Status == "unknown_format"
		or Z.Status == "invalid_record" ) then
		-- A read that worked clears both the wait and a foreign record seen
		-- earlier. The keeper reads until it really has the file, so the
		-- first answer is not necessarily the last one.
		Z.Status = "committed"
	end

	if readable then
		if Z.dirty then
			-- Something was changed before the record could be read. Those
			-- keys win and everything else is filled in from the record:
			-- writing what is in hand straight over it would be a handful
			-- of settings over everything ever saved.
			for dvar, value in pairs( saved ) do
				if Z.pending == nil or not Z.pending[dvar] then
					Z.saved[dvar] = value
				end
			end
		else
			Z.saved = saved
		end
		-- The record is reachable, which is the thing a write needs to
		-- know. It is set here and nowhere else: a read that failed is not
		-- permission to write, and marking it loaded off one would leave
		-- every change for the rest of the session unwritable.
		Z.loaded = true
	end

	-- Only a record that was actually read counts as one that has been put
	-- back. Marking the restore done off a read that failed is a game
	-- running on defaults with a full save file sitting beside it.
	if readable and Z.Get( "zs_lobby_restored" ) ~= "1" then
		-- The record holds exceptions only, so putting it back means both
		-- halves: the values it carries, and **the declared default for every
		-- row it does not**. Leaving those alone lets a dvar left over from
		-- earlier in this game resurrect a setting a reset already took out
		-- of the record -- gone from storage and still in the game.
		for _, row in ipairs( Z.AllRows ) do
			local value = Z.saved[row.dvar]
			if value == nil then
				value = row.default
			end
			if value ~= nil then
				Z.Set( controller, row.dvar, value, row )
			end
		end
		-- Anything another component registered, which ZShare has no default
		-- for and does not own. Its own rows are already written above, so
		-- they are stepped over rather than set twice.
		local mine = {}
		for _, row in ipairs( Z.AllRows ) do
			mine[row.dvar] = true
		end
		for dvar, value in pairs( Z.saved ) do
			if not mine[dvar] then
				Z.Set( controller, dvar, value )
			end
		end
		Z.Set( controller, "zs_lobby_restored", "1" )
	end
end

-- Neither half of the save can be relied on to be possible at the moment it
-- is asked for. A match often cannot reach the mod's storage, the frontend's
-- own timer runs for a minute and stops, and in a bundle ZShare's page may
-- never be opened at all -- the settings row belongs to whichever Z mod drew
-- it. So this keeps looking: it reads the record until it has it, and writes
-- whatever is outstanding as soon as the storage will take it.
--
-- Without it, a change made from the pause menu is a dvar and nothing more:
-- gone when the game closes, and the game after it runs on the defaults.
Z.Keeper = function ()
	-- The lobby button as well, for a route whose frontend the map check at
	-- the bottom of this file does not recognise. Both are guarded against a
	-- second pass.
	Z.Hook()

	if not Z.loaded or Z.dirty then
		local controller = Engine.GetPrimaryController()
		if controller == nil or controller < 0 then
			return
		end
		if not Z.loaded then
			pcall( Z.Startup, controller )
		end
		if Z.dirty then
			pcall( Z.Flush, controller )
		end
	end
end

-- The save files are read a moment after the frontend starts, so this looks
-- once a second until they are in -- or, after a minute of the game not
-- saying so, reads them anyway.
Z.Wait = function ( parent, tries )
	parent:addElement( LUI.UITimer.newElementTimer( 1000, true, function ()
		Z.Hook()
		local controller = Engine.GetPrimaryController()
		if controller ~= nil and controller >= 0 then
			local ok, ready = pcall( Engine.StorageIsFileReady, controller, Z.STORAGE )
			if ok and ready == true or tries >= 60 then
				Z.Startup( controller )
				return
			end
		end
		-- Every attempt counts, not only the ones that found a controller.
		-- Counting those alone meant a frontend with no primary controller
		-- never reached the minute, and each pass adds a timer element --
		-- so it added one a second for as long as the game was open.
		if tries >= 60 then
			return
		end
		Z.Wait( parent, tries + 1 )
	end ) )
end

-- ------------------------------------------------------------------------
-- The shared tab registry
--
-- CoD.ZBundleSettings is the one seam between the Z mods' menus: each writes
-- its categories into it and the shell draws whatever is there. Whoever loads
-- first builds it, so this creates it only when it is not already there and
-- never replaces a function somebody else put in -- two copies of the same
-- registry would be two half-filled menus.
--
-- ZShare never reads another component's storage or writes to it. A tab that
-- is not ours is drawn from its own get/set/flush/reset, and one that
-- registered none is drawn read-only rather than saved into ZShare's record.
-- ------------------------------------------------------------------------

-- Created at the top of this file, because functions above this point read
-- it and a `local` is only in scope after its own line: a body written above
-- the declaration sees a nil global instead, which compiles perfectly and
-- fails the first time a row is built.
--
-- This copy arrives through core_mod, whose zone links the shared artwork.
-- The generated loose ui_scripts copy changes only this delivery capability.
B.BackgroundImageAvailable = B.BackgroundImageAvailable or false
B.Tabs = B.Tabs or {}
B.TabById = B.TabById or {}
B.Components = B.Components or {}
B.ComponentById = B.ComponentById or {}
B.Actions = B.Actions or {}
B.ActionById = B.ActionById or {}

-- A component is a whole mod rather than one of its categories: what the
-- bundle's MODS page switches on and off, and what the title names as the
-- owner of the category on screen. Registering an id already known updates
-- that descriptor in place, so a mod loaded later -- which on T7x can be
-- this very module, loaded again over a live one -- corrects its own
-- registration without orphaning the table an open menu is holding.
B.RegisterComponent = B.RegisterComponent or function ( component )
	if type( component ) ~= "table" or type( component.id ) ~= "string" or component.id == "" then
		return
	end
	local existing = B.ComponentById[component.id]
	if existing ~= nil then
		for key, value in pairs( component ) do
			existing[key] = value
		end
		return existing
	end
	B.ComponentById[component.id] = component
	table.insert( B.Components, component )
	return component
end

-- The components in the order their categories are shown in: ZTweaks 0,
-- ZShare 100, ZShare 200, ZStats 300.
B.GetComponents = B.GetComponents or function ()
	local result = {}
	for _, component in ipairs( B.Components ) do
		table.insert( result, component )
	end
	table.sort( result, function ( left, right )
		local leftOrder = tonumber( left.order ) or 1000
		local rightOrder = tonumber( right.order ) or 1000
		if leftOrder ~= rightOrder then
			return leftOrder < rightOrder
		end
		return tostring( left.label or left.id ) < tostring( right.label or right.id )
	end )
	return result
end

-- What each mod on this screen calls its own build. The descriptor's own
-- `version` is the authority; a component registered by an older build that
-- has none is looked up in its public settings namespace instead, and one
-- that cannot be found at all reads as v? rather than being left out -- an
-- incomplete registration should be visible while it is being written.
B.ComponentVersions = B.ComponentVersions or {}

B.ComponentVersion = B.ComponentVersion or function ( component, controller )
	if component == nil then
		return nil
	end
	local value = component.version or component.getVersion
		or B.ComponentVersions[component.id]
	if type( value ) == "function" then
		local ok, result = pcall( value, controller, component )
		value = ok and result or nil
	end
	if value == nil or value == "" then
		local legacy = {
			ztweaks = CoD.ZTweaksSettings,
			zpause = CoD.ZPauseSettings,
			zshare = CoD.ZShareSettings,
			zstats = CoD.ZStatsSettings
		}
		local settings = legacy[string.lower( tostring( component.id or "" ) )]
		if settings ~= nil then
			value = settings.Version or settings.version
		end
	end
	if value == nil or value == "" then
		return nil
	end
	-- A version writes itself with or without the v; the line puts one on.
	return string.gsub( tostring( value ), "^%s*[vV]", "" )
end

-- Every registered mod, switched on or not: what is installed is what the
-- line is for. The bundle's own version is deliberately not in it.
B.ComponentVersionsText = B.ComponentVersionsText or function ( controller )
	local labels = {}
	for _, component in ipairs( B.GetComponents() ) do
		local label = string.upper( tostring( component.label or component.id or "MOD" ) )
		local version = B.ComponentVersion( component, controller ) or "?"
		table.insert( labels, label .. " v" .. version )
	end
	return table.concat( labels, " / " )
end

-- Whether a component is switched on. One that registered no getEnabled is
-- taken as on: a mod that cannot say is running, or it would not be here to
-- be asked.
B.ComponentEnabled = B.ComponentEnabled or function ( component, controller )
	if component == nil or type( component.getEnabled ) ~= "function" then
		return true
	end
	local ok, value = pcall( component.getEnabled, controller, component )
	if not ok then
		return true
	end
	return value ~= false and value ~= 0 and value ~= "0"
end

B.SetComponentEnabled = B.SetComponentEnabled or function ( component, controller, enabled )
	if component == nil or type( component.setEnabled ) ~= "function" then
		return false
	end
	local ok = pcall( component.setEnabled, controller, enabled, component )
	return ok
end

-- A mod switched on or off has to show on the page at once, and a component's
-- own getEnabled cannot always answer that quickly: the value it reads is a
-- dvar another write has yet to reach, or a save file, or a next-match state.
-- What was asked for is therefore what the open menu goes by, while the
-- component keeps sole ownership of storing it and of what happens next match.
--
-- Written as an upgrade over whatever is already here rather than as another
-- `or`: a packaged mod and a loose T7x ui_scripts copy share this registry and
-- either may have loaded first, so the pair that arrived first is wrapped in
-- place. The version guard is what keeps that to once.
B.ComponentEnabledOverrides = B.ComponentEnabledOverrides or {}

if ( tonumber( B.LiveComponentToggleVersion ) or 0 ) < 1 then
	local inheritedEnabled = B.ComponentEnabled
	local inheritedSetEnabled = B.SetComponentEnabled

	B.ComponentEnabled = function ( component, controller )
		if component ~= nil and component.id ~= nil
			and B.ComponentEnabledOverrides[component.id] ~= nil then
			return B.ComponentEnabledOverrides[component.id]
		end
		return inheritedEnabled( component, controller )
	end

	B.SetComponentEnabled = function ( component, controller, enabled )
		local ok, accepted = inheritedSetEnabled( component, controller, enabled )
		if ok == false or accepted == false then
			return false
		end
		if component ~= nil and component.id ~= nil then
			B.ComponentEnabledOverrides[component.id] = enabled == true
		end
		return true
	end

	B.LiveComponentToggleVersion = 1
end

-- One mod's settings, or several mods' on one screen. Everything the page
-- calls itself follows from this.
B.IsBundle = B.IsBundle or function ()
	return #B.GetComponents() > 1
end

-- An action is a press rather than a setting -- ZPause's pause is the first
-- of them -- and belongs to the lists the game's own menus draw. The registry
-- holds them so one merged pause menu can show everybody's without knowing
-- what any of them do. ZShare registers none: everything it does is a prompt
-- in the world. It still carries this, because in a bundle whichever mod
-- loaded first is the one whose copy runs.
B.RegisterAction = B.RegisterAction or function ( action )
	if type( action ) ~= "table" or type( action.id ) ~= "string" or action.id == "" then
		return
	end
	local existing = B.ActionById[action.id]
	if existing ~= nil then
		for key in pairs( existing ) do
			existing[key] = nil
		end
		for key, value in pairs( action ) do
			existing[key] = value
		end
		return
	end
	B.ActionById[action.id] = action
	table.insert( B.Actions, action )
end

-- The actions worth drawing right now. visible() is asked every time rather
-- than cached: whether a mod can do what its row offers is a thing that
-- changes while the game runs.
B.GetActions = B.GetActions or function ( controller )
	local result = {}
	for _, action in ipairs( B.Actions ) do
		local shown = true
		if type( action.visible ) == "function" then
			local ok, value = pcall( action.visible, controller, action )
			shown = ok and value ~= false
		end
		if shown and B.ComponentEnabled( B.ComponentById[action.owner], controller ) then
			table.insert( result, action )
		end
	end
	table.sort( result, function ( left, right )
		local leftOrder = tonumber( left.order ) or 1000
		local rightOrder = tonumber( right.order ) or 1000
		if leftOrder ~= rightOrder then
			return leftOrder < rightOrder
		end
		return tostring( left.id ) < tostring( right.id )
	end )
	return result
end

-- The words on an action's row, which for a toggle depend on what the game
-- is doing -- ZPause's reads PAUSE GAME, or UNPAUSE GAME while it is paused
-- -- so the label may be a function and is asked each time.
B.ActionLabel = B.ActionLabel or function ( action, controller )
	local label = action ~= nil and action.label or nil
	if type( label ) == "function" then
		local ok, value = pcall( label, controller, action )
		label = ok and value or nil
	end
	return tostring( label or ( action ~= nil and action.id ) or "" )
end

B.ActionEnabled = B.ActionEnabled or function ( action, controller )
	if action == nil or type( action.enabled ) ~= "function" then
		return true
	end
	local ok, value = pcall( action.enabled, controller, action )
	if not ok then
		return true
	end
	return value ~= false
end

-- A second registration of the same id replaces that descriptor in place,
-- rather than adding another or swapping the table: a menu already built
-- holds a reference to it, and on T7x a module can be loaded again over a
-- live one.
B.RegisterTab = B.RegisterTab or function ( tab )
	if type( tab ) ~= "table" or type( tab.id ) ~= "string" or tab.id == "" then
		return
	end
	local existing = B.TabById[tab.id]
	if existing ~= nil then
		for key in pairs( existing ) do
			existing[key] = nil
		end
		for key, value in pairs( tab ) do
			existing[key] = value
		end
		return
	end
	B.TabById[tab.id] = tab
	table.insert( B.Tabs, tab )
	-- A mod written against the older registry registers categories and no
	-- component. It still belongs on the MODS page, so one is made from what
	-- the category says about its owner -- without the enable callbacks,
	-- which makes it a row that reports rather than switches.
	if tab.owner ~= nil and tab.owner ~= "zbundle" and B.ComponentById[tab.owner] == nil then
		B.RegisterComponent( {
			id = tab.owner,
			label = tab.ownerLabel or tab.owner,
			order = tab.ownerOrder or tab.order
		} )
	end
end

-- The order the tabs are drawn in, which has to be the same whichever mod
-- happened to load first. MODS is the bundle's own and comes before
-- everything; CHANGED is the bundle's own and comes after everything;
-- between them each component's categories sit together, in the component's
-- order and then their own -- ZTweaks 1-99, ZShare 100, ZShare 200,
-- ZStats 300.
--
-- A component switched off keeps its place on MODS and loses its categories,
-- since there is nothing to edit for a mod that will not be there next
-- match. CHANGED stays: it is the shell's own.
-- READ ONLY is a shared predicate rather than display text anybody trusts,
-- and it covers more than the boundary: an informational row -- a CHANGED
-- copy, somebody else's compatibility report -- carries the same answer
-- under redundant names so a bundle of mixed versions cannot read it as
-- editable. Row contract v2 adds a per-row `enabled`, which a component may
-- make a callback, so a condition that changes while the page is open is
-- asked again rather than remembered. v3 adds the other half of that: a
-- `forcedValue`, which is the owner saying what the setting *is* for now
-- rather than what the menu may do with it. A locked row shows the forced
-- value and nothing else, and the saved preference underneath it is not
-- touched -- the owner puts it back by releasing the lock, which is why
-- `forcedValue` may be a callback returning nil.
--
-- Written as an upgrade over whatever registry arrived first, like the two
-- beside it: an older copy's idea of read-only would otherwise decide it for
-- the whole screen. Function for function and string for string with the
-- reference implementation, because in a bundle only one of these copies
-- runs and a row must not read differently depending on load order.
if ( tonumber( B.RowWritableVersion ) or 0 ) < 3 then
	B.RowEnabled = function ( row, tab, controller )
		if type( row ) ~= "table" then
			return false
		end
		local enabled = row.enabled
		if type( enabled ) == "function" then
			local ok, result = pcall( enabled, controller or 0, row, tab )
			if not ok then
				return false
			end
			enabled = result == true or result == 1 or result == "1"
		end
		return enabled ~= false and enabled ~= 0 and enabled ~= "0"
	end

	-- The forced value and whether there is one. A callback that throws, or
	-- answers with something no selector could show, locks the row with no
	-- value rather than leaving it editable: failing closed is the whole
	-- point of an override.
	B.RowOverride = function ( row, tab, controller )
		if type( row ) ~= "table" then
			return nil, false
		end
		local value = row.forcedValue
		if type( value ) == "function" then
			local ok, result = pcall( value, controller or 0, row, tab )
			if not ok then
				return nil, true
			end
			value = result
		end
		if value == nil then
			return nil, false
		end
		if value == true then
			value = "1"
		elseif value == false then
			value = "0"
		end
		if type( value ) ~= "string" and type( value ) ~= "number" then
			return nil, true
		end
		return tostring( value ), true
	end

	B.RowUnavailable = function ( row, tab, controller )
		local _, locked = B.RowOverride( row, tab, controller )
		return locked or not B.RowEnabled( row, tab, controller )
	end

	-- **The same pair is named twice across the Z mods**, and the version
	-- flag above is what stops the second copy defining its own: ZTweaks and
	-- ZShare ask B.RowOverride and get ( value, locked ), ZPause asks
	-- B.RowForced and gets ( locked, value ), with B.RowForcedValue beside
	-- it. Whichever block runs is the only one that does, so this one carries
	-- every name in its own argument order -- otherwise a bundle is a nil
	-- call in somebody's renderer, decided by load order.
	B.RowForced = function ( row, tab, controller )
		local value, locked = B.RowOverride( row, tab, controller )
		return locked, value
	end

	B.RowForcedValue = function ( row, tab, controller )
		local _, value = B.RowForced( row, tab, controller )
		return value
	end

	-- What the row says about itself while it cannot be written: the owner's
	-- own words where it gave any, and the state otherwise. A row that is
	-- merely editable gets its ordinary hint back.
	B.RowReason = function ( row, tab, controller )
		local value, locked = B.RowOverride( row, tab, controller )
		if locked then
			local reason = row.overrideReason
			if type( reason ) == "function" then
				local ok, result = pcall( reason, controller or 0, row, tab )
				reason = ok and result or nil
			end
			if reason ~= nil and reason ~= false then
				return tostring( reason )
			end
			return value == nil and "Override unavailable" or "Locked to " .. string.upper( value )
		end
		if not B.RowEnabled( row, tab, controller ) then
			return row.disabledReason or row.hint or ""
		end
		return row.hint or ""
	end

	B.RowWritable = function ( row, tab, controller )
		if type( row ) ~= "table" then
			return false
		end
		if row.boundary == "READ ONLY" or row.ztReadOnly == true
			or row.readOnly == true or row.writable == false or row.editable == false then
			return false
		end
		if tab ~= nil and ( tab.role == "report" or tab.role == "changed" ) then
			return false
		end
		return not B.RowUnavailable( row, tab, controller ) and #( row.values or {} ) > 0
	end

	B.RowWritableVersion = 3
end

-- Row contract v5: **a setting a client cannot affect is not a setting they
-- may edit.** Every ZShare row is the host's -- the trade rules, the costs,
-- the perk limit, the sounds every player hears -- so nothing here is
-- personal; the reason this is carried at all is that in a bundle ZShare's
-- renderer draws everybody's rows, and ZTweaks' character preferences are
-- personal. A screen that let a client change the host's rules would be
-- changing a dvar on their own machine and nothing else.
--
-- Written over whatever v3 arrived first rather than replacing it: the four
-- predicates it wraps are captured here and asked after the host lock, so a
-- disabled or locked row stays disabled or locked for the host too.
--
-- Function for function and string for string with the reference, including
-- the two sentences a locked row shows -- one copy of this runs for the whole
-- screen, and a row must not read differently depending on load order.
if ( tonumber( B.RowWritableVersion ) or 0 ) < 5 then
	local priorEnabled, priorUnavailable, priorReason, priorWritable = B.RowEnabled, B.RowUnavailable, B.RowReason, B.RowWritable

	-- Who is asking. The active lobby's own model first and the direct API
	-- second; a missing model is not a host. An answer that is neither true
	-- nor false is UNKNOWN rather than a guess, because the one thing worse
	-- than locking a host out is letting a client write.
	B.HostStatus = function ( controller )
		controller = controller or Engine.GetPrimaryController()
		local lobby = Enum.LobbyType.LOBBY_TYPE_PRIVATE
		local okGame, gameActive = pcall( Engine.IsLobbyActive, Enum.LobbyType.LOBBY_TYPE_GAME )
		local okInGame, inGame = pcall( Engine.IsInGame )
		if not ( okInGame and ( inGame == true or inGame == 1 ) ) and
			( not okGame or ( gameActive ~= true and gameActive ~= false and gameActive ~= 0 and gameActive ~= 1 ) ) then return "UNKNOWN" end
		if okGame and ( gameActive == true or gameActive == 1 ) or okInGame and ( inGame == true or inGame == 1 ) then lobby = Enum.LobbyType.LOBBY_TYPE_GAME end
		local ok, modelValue = pcall( function ()
			local root = DataSources.LobbyRoot.getModel( controller )
			local name = lobby == Enum.LobbyType.LOBBY_TYPE_GAME and "gameClient.isHost" or "privateClient.isHost"
			local model = Engine.GetModel( root, name )
			if model ~= nil then return Engine.GetModelValue( model ) end
		end )
		if ok and modelValue ~= nil then
			if modelValue == true or modelValue == 1 or modelValue == "1" then return "HOST" end
			if modelValue == false or modelValue == 0 or modelValue == "0" then return "CLIENT" end
		end
		local directOk, direct = pcall( Engine.IsLobbyHost, lobby )
		if directOk then
			if direct == true or direct == 1 then return "HOST" end
			if direct == false or direct == 0 then return "CLIENT" end
		end
		return "UNKNOWN"
	end

	-- A row is the host's unless it says otherwise, and only the exact word
	-- opts out: a misspelling must not hand a client the host's settings. A
	-- report tab is somebody's local diagnostic and belongs to whoever is
	-- reading it.
	B.RowAuthority = function ( row, tab )
		if tab ~= nil and tab.role == "report" then return "player" end
		local authority = row ~= nil and row.authority or nil
		if authority == nil and tab ~= nil then authority = tab.authority end
		return authority == "player" and "player" or "host"
	end

	B.RowHostLocked = function ( row, tab, controller )
		return row ~= nil and B.RowAuthority( row, tab ) == "host" and B.HostStatus( controller ) ~= "HOST"
	end

	-- What a locked row shows instead of a value. **Never the client's own
	-- saved dvar**: it is their machine's copy, not the host's live setting,
	-- and showing it as the host's is the one answer that reads as true and
	-- is not.
	B.RowHostValue = function ( row, tab, controller )
		return B.RowHostLocked( row, tab, controller ) and "HOST VALUE UNAVAILABLE" or nil
	end

	B.RowEnabled = function ( row, tab, controller )
		return not B.RowHostLocked( row, tab, controller ) and priorEnabled( row, tab, controller )
	end

	B.RowUnavailable = function ( row, tab, controller )
		return B.RowHostLocked( row, tab, controller ) or priorUnavailable( row, tab, controller )
	end

	B.RowReason = function ( row, tab, controller )
		if B.RowHostLocked( row, tab, controller ) then
			return B.HostStatus( controller ) == "UNKNOWN" and "Host status unknown; this host-controlled setting is locked." or "Only the host can change this setting. The host's current value is unavailable here."
		end
		return priorReason( row, tab, controller )
	end

	B.RowWritable = function ( row, tab, controller )
		return not B.RowHostLocked( row, tab, controller ) and priorWritable( row, tab, controller )
	end

	-- A client's local component toggle says nothing about the host's mod.
	-- Keep personal rows and locked host pages reachable; explicit tab gates
	-- still apply. Define here to upgrade an older registry/load-order winner.
	B.TabEnabled = function ( tab, controller )
		if tab == nil then return false end
		if tab.role == "mods" then return true end
		local component = B.ComponentById[tab.owner]
		if B.HostStatus( controller ) == "HOST" and component ~= nil and not B.ComponentEnabled( component, controller ) then return false end
		if type( tab.enabled ) ~= "function" then return tab.enabled ~= false end
		local ok, value = pcall( tab.enabled, controller, tab )
		return ok and value ~= false
	end

	B.RowWritableVersion = 5
end

-- **A version flag is not proof that a name exists.** The published four-mod
-- order is ZPause, ZShare, ZStats, ZTweaks: ZPause sets the version to 5 and
-- defines B.RowForced, so every block below that version -- including both of
-- the ones above -- is skipped, and B.RowOverride is never defined by anybody.
-- ZTweaks' CHANGED producer calls it for an ordinary unforced row, the native
-- renderer swallows the nil call with a pcall, and the category reads as empty
-- and disabled. That is the defect in the published bundle.
--
-- So this sits outside every gate and runs on its own terms: whichever of the
-- pair is missing is built from the one that is there, and a copy that already
-- works is never replaced. **Not an alias** -- the two return their answers in
-- the opposite order -- and not a reimplementation either: everything the
-- contract asks to be preserved, the controller fallback, the normalization
-- and the fail-closed answer for a predicate that throws, lives in whichever
-- implementation is being delegated to.
if type( B.RowOverride ) ~= "function" and type( B.RowForced ) == "function" then
	B.RowOverride = function ( row, tab, controller )
		local locked, value = B.RowForced( row, tab, controller )
		return value, locked
	end
end

if type( B.RowForced ) ~= "function" and type( B.RowOverride ) == "function" then
	B.RowForced = function ( row, tab, controller )
		local value, locked = B.RowOverride( row, tab, controller )
		return locked, value
	end
end

if type( B.RowForcedValue ) ~= "function" and type( B.RowForced ) == "function" then
	B.RowForcedValue = function ( row, tab, controller )
		local _, value = B.RowForced( row, tab, controller )
		return value
	end
end

-- The same again for the pair's companion, which ZPause's set does not carry
-- and ZStats' and ZTweaks' renderers ask for.
if type( B.RowUnavailable ) ~= "function" and type( B.RowEnabled ) == "function"
	and type( B.RowOverride ) == "function" then
	B.RowUnavailable = function ( row, tab, controller )
		local _, locked = B.RowOverride( row, tab, controller )
		return locked or not B.RowEnabled( row, tab, controller )
	end
end

-- The order every port shows them in, kept in one place so the upgrade below
-- and whatever built the registry first cannot disagree about it.
B.SortTabs = B.SortTabs or function ( left, right )
	if left.role == "mods" or right.role == "changed" then
		return true
	end
	if right.role == "mods" or left.role == "changed" then
		return false
	end
	local leftOwner = B.ComponentById[left.owner]
	local rightOwner = B.ComponentById[right.owner]
	local leftOwnerOrder = tonumber( leftOwner ~= nil and leftOwner.order ) or 1000
	local rightOwnerOrder = tonumber( rightOwner ~= nil and rightOwner.order ) or 1000
	if leftOwnerOrder ~= rightOwnerOrder then
		return leftOwnerOrder < rightOwnerOrder
	end
	local leftOrder = tonumber( left.order ) or 1000
	local rightOrder = tonumber( right.order ) or 1000
	if leftOrder ~= rightOrder then
		return leftOrder < rightOrder
	end
	return tostring( left.label or left.id ) < tostring( right.label or right.id )
end

-- Visibility and enabled state are different questions, and the registry
-- keeps them apart. Visible is whether a category exists on this build at
-- all; enabled is whether it can be walked into now, which is the tab's own
-- answer composed with its owner's switch on the MODS page.
B.TabVisible = B.TabVisible or function ( tab, controller )
	if tab == nil then
		return false
	end
	if type( tab.visible ) ~= "function" then
		return tab.visible ~= false
	end
	local ok, value = pcall( tab.visible, controller, tab )
	return ok and value ~= false
end

B.TabEnabled = B.TabEnabled or function ( tab, controller )
	if tab == nil then
		return false
	end
	-- MODS is how a switched-off mod is switched back on, so it is never
	-- the thing that gets switched off.
	if tab.role == "mods" then
		return true
	end
	local component = B.ComponentById[tab.owner]
	if component ~= nil and not B.ComponentEnabled( component, controller ) then
		return false
	end
	if type( tab.enabled ) ~= "function" then
		return tab.enabled ~= false
	end
	local ok, value = pcall( tab.enabled, controller, tab )
	return ok and value ~= false
end

B.GetTabs = B.GetTabs or function ( controller )
	local result = {}
	for _, tab in ipairs( B.Tabs ) do
		if tab.role == "changed" or B.ComponentEnabled( B.ComponentById[tab.owner], controller ) then
			table.insert( result, tab )
		end
	end
	if B.IsBundle() and B.ModsTab ~= nil then
		table.insert( result, B.ModsTab )
	end
	table.sort( result, function ( left, right )
		if left.role == "mods" or right.role == "changed" then
			return true
		end
		if right.role == "mods" or left.role == "changed" then
			return false
		end
		local leftOwner = B.ComponentById[left.owner]
		local rightOwner = B.ComponentById[right.owner]
		local leftOwnerOrder = tonumber( leftOwner ~= nil and leftOwner.order ) or 1000
		local rightOwnerOrder = tonumber( rightOwner ~= nil and rightOwner.order ) or 1000
		if leftOwnerOrder ~= rightOwnerOrder then
			return leftOwnerOrder < rightOwnerOrder
		end
		local leftOrder = tonumber( left.order ) or 1000
		local rightOrder = tonumber( right.order ) or 1000
		if leftOrder ~= rightOrder then
			return leftOrder < rightOrder
		end
		return tostring( left.label or left.id ) < tostring( right.label or right.id )
	end )
	return result
end

-- A switched-off mod keeps its categories on the strip, greyed and not to be
-- walked into, rather than having them vanish: a bundle stays readable as the
-- set of mods installed in it, and MODS -- the one page that can switch a mod
-- back on -- is never the page that disappeared. GetTabs therefore filters on
-- visibility alone and the ports grey what TabEnabled refuses.
--
-- Replaced in place rather than written with `or`: a loose ui_scripts copy and
-- a packaged one share this registry and either may have loaded first, so an
-- older copy's filtering has to be upgraded rather than left running.
if ( tonumber( B.DisabledTabVisibilityVersion ) or 0 ) < 1 then
	local sortTabs = B.SortTabs

	B.GetTabs = function ( controller )
		local result = {}
		for _, tab in ipairs( B.Tabs ) do
			if B.TabVisible( tab, controller ) then
				table.insert( result, tab )
			end
		end
		if B.IsBundle() and B.ModsTab ~= nil and B.TabVisible( B.ModsTab, controller ) then
			table.insert( result, B.ModsTab )
		end
		table.sort( result, sortTabs )
		return result
	end

	B.DisabledTabVisibilityVersion = 1
end

Z.Owner = "zshare"

-- Black Ops III hands get() the dvar and the row; a dvar belongs to no
-- controller, so there is none to take. The dvar is the live value, which is
-- the whole point: the script reads the same one.
Z.TabGet = function ( dvar, row )
	-- Black Ops III's contract is get( dvar, row ) and that is what this
	-- publishes, but not every shell calls it that way: ZTweaks' own Black
	-- Ops III renderer passes ( controller, dvar, row ), the Black Ops II
	-- shape. Read that way the controller would be taken for the dvar, every
	-- ZShare row would read empty, and the page would show DEFAULT over a
	-- saved value. Three arguments with a number in front is that call, and
	-- it is shifted rather than believed.
	if row ~= nil and type( dvar ) ~= "string" then
		return Z.Get( row )
	end
	return Z.Get( dvar )
end

-- The one place a setting is written. The dvar is the live value and the save
-- record follows it, so a change made here is in the running game at the next
-- press and still there the next time the game starts.
Z.TabSet = function ( controller, dvar, value, row )
	if value == "" and row ~= nil and row.default ~= nil then
		value = row.default
	end
	Z.Set( controller, dvar, value, row )
	-- Which settings this session has an opinion about, kept apart from
	-- their values: a setting put back to DEFAULT is remembered by having
	-- been touched, since its value is its absence. It is what lets a
	-- record read after a change was made be merged with rather than
	-- written over.
	Z.pending = Z.pending or {}
	Z.pending[dvar] = true
	if value == "" then
		-- DEFAULT saves nothing, so the setting keeps following whatever
		-- default the script carries rather than being pinned to this
		-- build's.
		Z.saved[dvar] = nil
	else
		Z.saved[dvar] = value
	end
	Z.dirty = true
end

Z.TabFlush = function ( controller, tab )
	Z.Flush( controller )
end

Z.TabReset = function ( controller, menu, tab )
	Z.ResetAll( controller, menu )
end

for _, page in ipairs( Z.Pages ) do
	B.RegisterTab( {
		id = page.id,
		-- The caption and the hint are resolved again when the page opens:
		-- this runs as the module loads, which in the frontend is before
		-- ZShare's own strings are anywhere to be found.
		label = Z.Text( page.titleKey, page.title ),
		labelKey = page.titleKey,
		labelText = page.title,
		hint = Z.Text( page.hintKey, page.hint ),
		hintKey = page.hintKey,
		hintText = page.hint,
		owner = Z.Owner,
		ownerLabel = "ZShare",
		-- Every ZShare setting is one of the host's: the rules the match runs
		-- on, the costs, and the sounds and lines every player gets. None of
		-- it is personal, and a client changing one would be writing a dvar
		-- on their own machine and nowhere else. Declared rather than left to
		-- the default so another mod's renderer reads it the same way.
		authority = "host",
		order = page.order,
		rows = page.rows,
		get = Z.TabGet,
		set = Z.TabSet,
		flush = Z.TabFlush,
		reset = Z.TabReset
	} )
end

-- ------------------------------------------------------------------------
-- ZShare as the bundle knows it
-- ------------------------------------------------------------------------

-- One row, one switch, and the description under it, on the bundle's MODS
-- page. zs_enabled is a real switch and not a cosmetic one -- the script
-- reads it as a match loads and installs nothing at all when it is off --
-- which is why the boundary says NEXT MATCH.
-- Order 200 is ZShare's block of the shared registry: ZTweaks owns 1-99,
-- ZPause 100, ZStats 300, so a bundle stacks everybody's categories in the
-- same order however the mods happened to load.
B.RegisterComponent( {
	id = Z.Owner,
	label = "ZShare",
	-- Which build this is, on the component rather than only on the page:
	-- a bundle's MODS row shows it for a mod that is switched off, and the
	-- page whose corner usually carries it may never be opened -- on this
	-- engine the settings row can belong to another mod entirely.
	version = Z.Version,
	order = 200,
	description = "Trading weapons with a teammate, giving points, and sharing or paying for the box, the Pack-a-Punch and the perk machines.",
	boundary = "NEXT MATCH",
	getEnabled = function ()
		local value = Z.Get( "zs_enabled" )
		return value == "" or value ~= "0"
	end,
	setEnabled = function ( controller, enabled )
		Z.TabSet( controller, "zs_enabled", enabled and "1" or "0" )
		Z.Flush( controller )
	end
} )

-- The two categories the shell owns rather than any one mod. Neither is
-- registered over one that is already there: whichever Z mod loaded first
-- brought its own, and one of each is the whole point of them.
if B.TabById["zbundle_changed"] == nil then
	B.RegisterTab( {
		id = "zbundle_changed",
		label = "CHANGED",
		hint = "Settings changed from their defaults, across every mod on this screen.",
		owner = "zbundle",
		ownerLabel = "ZBundle",
		order = 1000000,
		role = "changed",
		rows = function ()
			local rows = {}
			for _, tab in ipairs( B.Tabs ) do
				if tab.role ~= "report" and tab.role ~= "changed" and tab.role ~= "mods" then
					for _, row in ipairs( Z.TabRows( tab ) ) do
						-- A button has nothing to differ from a default.
						local current = row.kind ~= "button" and Z.RowGet( row, tab ) or ""
						-- A host-owned row read on a client is that client's own
						-- copy of the dvar, which says nothing about what the
						-- host changed. Listing it would report their machine as
						-- the match's settings.
						if not Z.IsDefault( current, row )
							and not B.RowHostLocked( row, tab ) then
							-- A copy: the row here reports, and the one on
							-- its own category is still the one that edits.
							-- Nothing here writes to another mod.
							local copy = {}
							for key, value in pairs( row ) do
								copy[key] = value
							end
							local label = string.upper( tostring( current ) )
							for index, value in ipairs( row.values or {} ) do
								if Z.Same( current, value ) then
									label = Z.ChoiceLabel( row, index, label )
									break
								end
							end
							-- Worded here, in the reader's language, from the source row's own
							-- keys - and then the keys come off, as boundaryKey always did below. A
							-- copy that kept them would be resolved by them wherever it is drawn: its
							-- label back to the bare setting name, its hint without this note, and its
							-- one choice by the first key of the source row's list. sourceOwner tells
							-- any renderer whose words these are; sourceTab is left off, because a
							-- renderer that has both prefixes the owner itself.
							copy.label = string.upper( tostring( tab.ownerLabel or tab.owner or "MOD" ) )
								.. " - " .. Z.RowLabel( row )
							copy.hint = Z.RowHint( row ) .. "  "
								.. Z.Format( "ui.changed_note", "Set on {owner}'s own category, which is where it can be changed.",
									{ owner = tostring( tab.ownerLabel or tab.owner or "this mod" ) } )
							copy.labelKey = nil
							copy.hintKey = nil
							copy.choiceKeys = nil
							copy.sourceOwner = tab.owner
							copy.boundary = "READ ONLY"
							-- Said four ways on purpose. A bundle of mixed
							-- versions may be rendered by a copy of the
							-- shell that knows only one of these names, and
							-- a CHANGED row read as editable is an edit
							-- made to a report.
							copy.readOnly = true
							copy.ztReadOnly = true
							copy.writable = false
							copy.editable = false
							copy.boundaryKey = nil
							copy.default = current
							copy.values = { current }
							copy.labels = { label }
							table.insert( rows, copy )
						end
					end
				end
			end
			return rows
		end
	} )
end

B.ModsTab = B.ModsTab or {
	id = "zbundle_mods",
	label = "MODS",
	hint = "Switch each mod on this screen on or off.",
	owner = "zbundle",
	ownerLabel = "ZBundle",
	order = -1000000,
	role = "mods",
	rows = function ()
		local rows = {}
		for _, component in ipairs( B.GetComponents() ) do
			table.insert( rows, {
				dvar = "zbundle_component_" .. component.id,
				label = string.upper( tostring( component.label or component.id ) ),
				hint = component.description or "Switch this mod on or off.",
				-- The description is the component's own sentence, so it is the component's
				-- localizer that translates it, in any renderer that reads the field.
				localizationOwner = component.id,
				-- A mod that registered no switch is reported and not moved.
				boundary = type( component.setEnabled ) == "function"
					and ( component.boundary or "NEXT MATCH" ) or "READ ONLY",
				scope = "HOST / SHARED",
				kind = "choice",
				default = "1",
				values = { "0", "1" },
				labels = { "OFF", "ON" },
				zsComponent = component
			} )
		end
		return rows
	end,
	get = function ( dvar, row )
		return B.ComponentEnabled( row.zsComponent, Engine.GetPrimaryController() ) and "1" or "0"
	end,
	set = function ( controller, dvar, value, row )
		B.SetComponentEnabled( row.zsComponent, controller, value ~= "0" )
	end
}

-- Who draws the shared rows. In a bundle every component's menu opens the
-- same screen and the same actions, so a row each would be the same row
-- four times: the first to load claims them, and a bundle's own loader
-- claims them ahead of everybody by setting these before anything else is
-- read. Standalone, ZShare claims them and draws them.
B.SettingsRowOwner = B.SettingsRowOwner or Z.Owner
B.ActionRowsOwner = B.ActionRowsOwner or Z.Owner

Z.DrawsSettingsRow = function ()
	return B.SettingsRowOwner == Z.Owner
end

Z.DrawsActionRows = function ()
	return B.ActionRowsOwner == Z.Owner
end

Z.TabLabel = function ( tab )
	return Z.Keyed( tab.labelKey, tab.labelText or tab.label, tab.id, tab.owner, nil, tab )
end

Z.TabHint = function ( tab )
	return Z.Keyed( tab.hintKey, tab.hintText or tab.hint, "", tab.owner, nil, tab )
end

Z.TabRows = function ( tab )
	if tab == nil then
		return {}
	end
	if type( tab.rows ) == "function" then
		local ok, rows = pcall( tab.rows )
		if ok and type( rows ) == "table" then
			return rows
		end
		return {}
	end
	return type( tab.rows ) == "table" and tab.rows or {}
end

-- Whether a category can be walked into: the registry's answer, plus the
-- shell's own for CHANGED, which is nothing to look at while nothing differs
-- from a default. A category that is not enabled stays on the strip, greyed.
Z.TabEnabled = function ( tab, controller )
	if not B.TabEnabled( tab, controller ) then
		return false
	end
	if tab ~= nil and tab.role == "changed" then
		return #Z.TabRows( tab ) > 0
	end
	return true
end

Z.FindTabByRole = function ( tabs, role )
	for _, tab in ipairs( tabs or {} ) do
		if tab.role == role then
			return tab
		end
	end
	return nil
end

Z.FindTab = function ( tabs, id )
	for _, tab in ipairs( tabs or {} ) do
		if tab.id == id then
			return tab
		end
	end
	return nil
end

Z.FindTabIndex = function ( tabs, id )
	for index, tab in ipairs( tabs or {} ) do
		if tab.id == id then
			return index
		end
	end
	return 1
end

-- The category a bumper press should land on, which is not always the cell
-- next door: a switched-off mod's categories are on the strip and greyed, and
-- those are stepped over. Bounded rather than wrapping, as the strip is.
-- The next category a press leads to, which is not always the cell next
-- door: a switched-off mod's categories stay on the strip, greyed, and are
-- stepped over.
--
-- Both ends wrap, which is Black Ops II's behaviour and the shell contract's
-- -- so this answers nil only when there is nowhere else to be, and the
-- arrows dim only when fewer than two categories can be walked into.
Z.AdjacentTabIndex = function ( menu, controller, direction )
	local tabs = menu ~= nil and menu.zsTabs or nil
	local count = #( tabs or {} )
	if count < 2 then
		return nil
	end
	local index = Z.FindTabIndex( tabs, menu.zsTabId )
	for _ = 1, count - 1 do
		index = index + direction
		if index < 1 then
			index = count
		elseif index > count then
			index = 1
		end
		if Z.TabEnabled( tabs[index], controller ) then
			return index
		end
	end
	return nil
end

-- Stock GridLayout normally skips a cell marked disabled. Some T7x builds
-- move focus onto it anyway, so the grid is stepped one cell at a time until
-- the category it reports is the one that was asked for. True when the page
-- has actually moved, which is what a hold asks before it takes another step.
Z.NavigateTab = function ( menu, controller, direction )
	if menu == nil or menu.Tabs == nil or menu.Tabs.grid == nil then
		return false
	end
	local target = Z.AdjacentTabIndex( menu, controller, direction )
	if target == nil then
		return false
	end
	local targetId = menu.zsTabs[target].id
	-- A step that wraps cannot be walked to: the grid will not move past its
	-- own edge, so the whole strip is rebuilt under a data-source identity it
	-- has not cached, with the destination selected. Walking it would spend
	-- the loop below on the edge cell and leave the page where it was.
	local current = Z.FindTabIndex( menu.zsTabs, menu.zsTabId )
	if ( direction < 0 and target > current ) or ( direction > 0 and target < current ) then
		Z.RefreshTabs( menu, controller, targetId )
		return true
	end
	for _ = 1, #menu.zsTabs do
		if direction < 0 then
			menu.Tabs.grid:navigateItemLeft()
		else
			menu.Tabs.grid:navigateItemRight()
		end
		if menu.zsTabId == targetId then
			return true
		end
	end
	return false
end

-- ------------------------------------------------------------------------
-- The lobby button
-- ------------------------------------------------------------------------

-- Holding a category arrow, LB/RB or Q/E walks the strip.
--
-- This page owns every step of the strip: the press itself is the first, then
-- 350 ms, then one every 225 ms until the key comes up -- long enough that a
-- tap is never two, short enough that fifteen categories is a hold rather than
-- fifteen presses. The stock tab list is told not to navigate, the LB/RB
-- callbacks are inert, and the four inputs that move it are read where a
-- key-down and a key-up can be told apart. It is the Z mods' shared menu kit's
-- route: the one before it let the stock strip take the first step and this
-- page the rest, and two owners of one strip is how a held key came to skip a
-- category or stall.
Z.StopTabHold = function ( menu )
	if menu == nil then
		return
	end
	menu.zsTabHoldSource = nil
	menu.zsTabHoldDirection = nil
	menu.zsTabHoldEpoch = ( menu.zsTabHoldEpoch or 0 ) + 1
	if menu.zsTabHoldTimer ~= nil then
		pcall( menu.zsTabHoldTimer.close, menu.zsTabHoldTimer )
		menu.zsTabHoldTimer = nil
	end
end

Z.TabHoldBlocked = function ( menu )
	return menu == nil or menu.occludedBy ~= nil
end

-- One timer at a time, armed again after each step rather than left
-- repeating, so a step that rebuilt the strip has finished before the next.
Z.TabHoldSchedule = function ( menu, epoch, delay, controller, direction )
	local ok, timer = pcall( LUI.UITimer.newElementTimer, delay, true, function ()
		menu.zsTabHoldTimer = nil
		if menu.zsTabHoldEpoch ~= epoch or menu.zsTabHoldSource == nil then
			return
		end
		if Z.TabHoldBlocked( menu ) or not Z.NavigateTab( menu, controller, direction ) then
			Z.StopTabHold( menu )
			return
		end
		if menu.zsTabHoldEpoch == epoch then
			Z.TabHoldSchedule( menu, epoch, 225, controller, direction )
		end
	end )
	if ok and timer ~= nil then
		menu.zsTabHoldTimer = timer
		menu:addElement( timer )
	else
		Z.StopTabHold( menu )
	end
end

Z.StartTabHold = function ( menu, controller, direction, source )
	if menu == nil or Z.TabHoldBlocked( menu ) then
		return
	end
	-- The same source holding the same way is the key repeating itself.
	if menu.zsTabHoldSource == source and menu.zsTabHoldDirection == direction then
		return
	end
	Z.StopTabHold( menu )
	menu.zsTabHoldSource = source
	menu.zsTabHoldDirection = direction
	local epoch = menu.zsTabHoldEpoch
	-- The press is the first step.
	local moved = Z.NavigateTab( menu, controller, direction )
	if menu.zsTabHoldEpoch ~= epoch then
		return
	end
	if not moved or Z.TabHoldBlocked( menu ) then
		Z.StopTabHold( menu )
		return
	end
	Z.TabHoldSchedule( menu, epoch, 350, controller, direction )
end

-- One edge state per input, merging the two roads it arrives on: the raw
-- gamepad_button event and the input's model. A real raw release wins, so a
-- model still reading down afterwards cannot start the hold again.
Z.TabHoldEdge = function ( menu, controller, source, direction, route, down )
	if menu == nil or type( down ) ~= "boolean" then
		return
	end
	menu.zsTabEdges = menu.zsTabEdges or {}
	local state = menu.zsTabEdges[source]
	if state == nil then
		state = {}
		menu.zsTabEdges[source] = state
	end
	if state[route] == down then
		return
	end
	state[route] = down
	if route == "raw" then
		state.rawSeen = down
	end
	if not down and ( route == "raw" or not state.rawSeen ) then
		state.pressed = false
		if menu.zsTabHoldSource == source then
			Z.StopTabHold( menu )
		end
	elseif down and not state.pressed then
		state.pressed = true
		Z.StartTabHold( menu, controller, direction, source )
	end
end

Z.TabHoldSources = {
	Q = -1,
	E = 1,
	LB = -1,
	RB = 1
}

-- Stock HandleButtonPress runs a key's callbacks and then clears its model to
-- zero -- an acknowledgement, not the key coming up -- so a held Q read as
-- released the instant it was acted on, and the stock tab list's own callback
-- took a step of its own. For this page's four strip inputs it only reads the
-- model: the step is this page's, and the model keeps the real state. Every
-- other button and every other menu keeps the stock handler.
Z.InstallHeldShortcutBitGuard = function ()
	if CoD.Menu == nil or type( CoD.Menu.HandleButtonPress ) ~= "function"
		or Z.HeldShortcutHandler == CoD.Menu.HandleButtonPress then
		return
	end
	local inherited = CoD.Menu.HandleButtonPress
	local wrapped = function ( menu, controller, button, model, ... )
		local models = menu ~= nil and menu.zsHeldShortcutModels or nil
		local source = models ~= nil and models[model] or nil
		if source == nil then
			return inherited( menu, controller, button, model, ... )
		end
		Z.TabHoldModel( menu, controller, source, model )
	end
	Z.HeldShortcutHandler = wrapped
	CoD.Menu.HandleButtonPress = wrapped
end

Z.TabHoldModel = function ( menu, controller, source, model )
	local usable = Engine.IsControllerBeingUsed( controller ) or menu.unusedControllerAllowed
	local down = false
	if usable then
		local ok, got = pcall( function ()
			return CoD.BitUtility.IsBitwiseAndNonZero( Engine.GetModelValue( model ), Enum.LUIButtonFlags.FLAG_DOWN )
		end )
		down = ok and got == true
	end
	Z.TabHoldEdge( menu, controller, source, Z.TabHoldSources[source], "model", down )
end

-- The pointer, which the strip's own arrows had no hold for. A press moves
-- one category and starts the hold; a click that wanders off the arrow is a
-- mouseleave rather than a mouseup, so both stop it, and the stock
-- button_action is suppressed for the press this already handled -- it would
-- be a second step for one click.
Z.AttachMouseTabHold = function ( menu, button, controller, direction )
	local source = direction < 0 and "mouse_left" or "mouse_right"
	button:registerEventHandler( "leftmousedown", function ( element, event )
		element.zsMouseTabPress = true
		Z.StartTabHold( menu, event.controller or controller, direction, source )
		return true
	end )
	button:registerEventHandler( "leftmouseup", function ()
		if menu.zsTabHoldSource == source then
			Z.StopTabHold( menu )
		end
		return true
	end )
	button:registerEventHandler( "mouseleave", function ()
		if menu.zsTabHoldSource == source then
			Z.StopTabHold( menu )
		end
	end )
end

-- Q, E and both bumpers, on the page's own terms. The stock strip never steps
-- on its own -- basicTabList's LB/RB callbacks read m_disableNavigation -- and
-- the four inputs are read from their models, the only place a release is
-- published, and from the raw event for a keyboard or pad that does not
-- publish bits.
Z.AttachTabHold = function ( menu, controller )
	if menu == nil then
		return
	end
	if menu.Tabs ~= nil then
		menu.Tabs.m_disableNavigation = true
	end

	menu.zsHeldShortcutModels = {}
	local root = Engine.GetModelForController( controller )
	for source, path in pairs( {
		Q = "KeyPressBits.Q",
		E = "KeyPressBits.E",
		LB = "ButtonBits." .. Enum.LUIButton.LUI_KEY_LB,
		RB = "ButtonBits." .. Enum.LUIButton.LUI_KEY_RB
	} ) do
		local ok, model = pcall( Engine.GetModel, root, path )
		if ok and model ~= nil then
			menu.zsHeldShortcutModels[model] = source
			menu:subscribeToModel( model, function ( changed )
				Z.TabHoldModel( menu, controller, source, changed )
			end, false )
		end
	end

	-- The same four as raw events. Consumed whatever happens: a press that
	-- fell through would be a second step. Anything else goes on to whatever
	-- was there before.
	local previous = menu.m_eventHandlers ~= nil and menu.m_eventHandlers.gamepad_button or nil
	menu:registerEventHandler( "gamepad_button", function ( element, event )
		local source = nil
		local button = event.button
		if button == "shoulderl" or button == "left_shoulder" or button == Enum.LUIButton.LUI_KEY_LB then
			source = "LB"
		elseif button == "shoulderr" or button == "right_shoulder" or button == Enum.LUIButton.LUI_KEY_RB then
			source = "RB"
		elseif button == "key_shortcut" and type( event.key ) == "string" then
			local key = string.upper( event.key )
			if key == "Q" or key == "E" then
				source = key
			end
		end
		if source ~= nil then
			Z.TabHoldEdge( element, event.controller or controller, source, Z.TabHoldSources[source], "raw", event.down )
			return true
		end
		if previous ~= nil then
			return previous( element, event )
		end
	end )
end

-- The one host test, which is the shared registry's. This read its own
-- model and **answered host when the model was missing** -- a lobby that
-- had not published one yet made every client the host of the screen. The
-- shared predicate falls back to the direct API instead and answers UNKNOWN
-- rather than guessing, and UNKNOWN is locked.
Z.IsHost = function ( controller )
	return B.HostStatus( controller ) == "HOST"
end

-- The three words the badge can say. UNKNOWN is its own answer and not a
-- quiet CLIENT: a page that cannot tell is a page whose locks are a guess,
-- and the player should be told that rather than left to work it out.
Z.HostBadgeText = function ( controller )
	local status = B.HostStatus( controller )
	if status == "HOST" then
		return Z.Text( "ui.host", "HOST" )
	end
	if status == "CLIENT" then
		return Z.Text( "ui.client", "CLIENT" )
	end
	return Z.Text( "ui.host_unknown", "HOST STATUS UNKNOWN" )
end

-- Whether this player has any business on the screen at all. The host always
-- does. A client does the moment something on it is theirs to change --
-- which standalone ZShare never has, since every one of its settings is one
-- of the host's dvars, and a bundle does as soon as another mod registers a
-- personal row.
--
-- Both halves matter. Offering a client a page where every row is locked is
-- a dead end dressed as a setting; hiding the page that holds their own
-- preferences because ZShare happens to be the mod drawing it is worse.
Z.EntryVisible = function ( controller )
	if B.HostStatus( controller ) == "HOST" then
		return true
	end
	-- Asked cheaply: the authority is a field on the row, and only a row
	-- that claims to be personal is worth the rest of the question. This runs
	-- every time the game builds its pause list, and B.HostStatus is engine
	-- calls -- one for the host test above, and none at all per row unless
	-- somebody has registered something personal.
	for _, tab in ipairs( B.GetTabs( controller ) ) do
		if tab.role ~= "report" and tab.role ~= "changed" and Z.TabEnabled( tab, controller ) then
			for _, row in ipairs( Z.TabRows( tab ) ) do
				if B.RowAuthority( row, tab ) == "player"
					and B.RowWritable( row, tab, controller ) then
					return true
				end
			end
		end
	end
	return false
end

-- In its own group, before the gum and build kit buttons every zombies lobby
-- ends with. One button, whoever drew it: in a bundle it opens everybody's
-- categories, so it is named for the screen rather than for ZShare.
Z.AddButton = function ( buttons, controller )
	local at = #buttons + 1
	for index, button in ipairs( buttons ) do
		if button.optionDisplay == "MENU_BUBBLEGUM_BUFFS_CAPS" then
			at = index
			break
		end
	end
	if at > 1 then
		buttons[at - 1].isLastButtonInGroup = true
	end
	table.insert( buttons, at, {
		optionDisplay = Z.MenuTitle( B.GetTabs( controller ) ),
		action = Z.OpenFromLobby,
		customId = "btnZShareSettings",
		isLargeButton = true,
		isLastButtonInGroup = true,
		disabled = false,
		selected = false,
		warning = false
	} )
end

-- The zombies lobbies a host starts a game from: online, where solo games
-- start, private, and LAN.
Z.Hook = function ()
	if Z.hooked or CoD.LobbyMenus == nil or CoD.LobbyMenus.AddButtonsForTarget == nil or LobbyData == nil or LobbyData.UITargets == nil then
		return
	end
	Z.hooked = true
	Z.Lobbies = {}
	for _, name in ipairs( {
		"UI_ZMLOBBYONLINE",
		"UI_ZMLOBBYONLINECUSTOMGAME",
		"UI_ZMLOBBYLANGAME"
	} ) do
		local target = LobbyData.UITargets[name]
		if target ~= nil then
			Z.Lobbies[target.id] = true
		end
	end
	local addButtonsForTarget = CoD.LobbyMenus.AddButtonsForTarget
	CoD.LobbyMenus.AddButtonsForTarget = function ( controller, id )
		local buttons = addButtonsForTarget( controller, id )
		if Z.Lobbies[id] and Z.EntryVisible( controller ) and Z.DrawsSettingsRow() then
			Z.AddButton( buttons, controller )
		end
		return buttons
	end
end

-- Opened the way the game opens its own bot settings from the lobby, so the
-- rest of the lobby sees the host is changing the rules.
Z.OpenFromLobby = function ( self, element, controller, param, menu )
	pcall( function ()
		CoD.LobbyBase.SetLeaderActivity( controller, CoD.LobbyBase.LeaderActivity.EDITING_GAME_RULES )
	end )
	local opened = OpenOverlay( menu, "ZShareSettings", controller )
	if opened ~= nil then
		LUI.OverrideFunction_CallOriginalFirst( opened, "close", function ()
			pcall( function ()
				CoD.LobbyBase.ResetLeaderActivity( controller )
			end )
		end )
	end
end

-- The other way in, from the game's own pause menu. A popup rather than an
-- overlay: the pause menu stays open underneath, the way its own options page
-- does, so the game is still paused behind the settings -- and in a bundle
-- ZPause's zp_pause_menu does not read stepping in here as a resume.
Z.OpenFromPause = function ( self, element, controller )
	Z.Startup( controller )
	local menu = self
	while menu ~= nil and menu.openMenu == nil do
		menu = menu:getParent()
	end
	if menu ~= nil then
		OpenPopup( menu, "ZShareInGameSettings", controller )
	end
end

-- ------------------------------------------------------------------------
-- The page
-- ------------------------------------------------------------------------

Z.Title = function ()
	return Z.Text( "ui.title", "ZSHARE SETTINGS" )
end

-- ZShare's own name while ZShare is all there is on the page, and the
-- bundle's the moment somebody else has registered a tab: a screen carrying
-- four mods' settings is not ZShare's settings. The pause-menu row is named
-- from this as well -- one screen, one name, wherever it is opened from.
Z.MenuTitle = function ( tabs )
	if B.IsBundle() then
		return "ZBUNDLE SETTINGS"
	end
	for _, tab in ipairs( tabs or {} ) do
		if tab.owner ~= Z.Owner and tab.owner ~= "zbundle" then
			return "ZBUNDLE SETTINGS"
		end
	end
	return Z.Title()
end

Z.OwnerLabel = function ( tab )
	if tab ~= nil and tab.ownerLabel ~= nil and tab.ownerLabel ~= "" then
		return tostring( tab.ownerLabel )
	end
	return "ZShare"
end

-- And the line at the top, which names the owner of the category on screen:
-- with four mods' settings in one place, whose a category is should never be
-- something to work out from where it sits in the strip.
Z.TabTitle = function ( tab, tabs )
	local title = Z.MenuTitle( tabs )
	if tab == nil or title == Z.Title() then
		return title
	end
	if tab.role == "mods" then
		return title .. " - " .. Z.Shell( "MODS" )
	end
	if tab.role == "changed" then
		return title .. " - " .. Z.Shell( "CHANGED" )
	end
	return title .. " - " .. string.upper( Z.OwnerLabel( tab ) )
end

-- The bundle's version, when a bundle is what is running. It sets this
-- itself; the dvar is the fallback for a build that has not.
Z.BundleVersion = function ()
	local value = B.BundleVersion or CoD.ZBundleVersion
	if type( value ) == "function" then
		local ok, result = pcall( value )
		value = ok and result or nil
	end
	if value == nil or value == "" then
		local dvar = Z.Get( "zbundle_version" )
		if dvar ~= "" then
			value = dvar
		end
	end
	return value
end

-- The image the Workshop build links into core_mod. BOIII and T7x read this
-- page out of ui_scripts, where there is no fastfile and so no way to
-- register an image of our own -- they get a half-transparent black panel
-- instead. One page, decided when it runs, rather than two pages to keep in
-- step.
--
-- The name is shared with Xep's other Black Ops III mods, which ship the same
-- artwork, so a bundle of them carries the image once.
Z.IMAGE = "zmods_menu_background_image"

Z.HasImage = function ()
	return B.BackgroundImageAvailable == true
end

Z.Backdrop = function ( menu )
	local background = LUI.UIImage.new()
	background:setLeftRight( true, true, 0, 0 )
	background:setTopBottom( true, true, 0, 0 )
	local hasBackgroundImage = Z.HasImage()
	if hasBackgroundImage then
		background:setImage( RegisterImage( Z.IMAGE ) )
	else
		background:setRGB( 0, 0, 0 )
		background:setAlpha( 0.5 )
	end
	menu:addElement( background )
	menu.Background = background

	-- Over the art, so a white list reads against it wherever the art is
	-- bright. The panel above is already dark enough on its own.
	local shade = LUI.UIImage.new()
	shade:setLeftRight( true, true, 0, 0 )
	shade:setTopBottom( true, true, 0, 0 )
	shade:setRGB( 0, 0, 0 )
	shade:setAlpha( hasBackgroundImage and 0.34 or 0 )
	menu:addElement( shade )
	menu.Shade = shade
end

-- What a row's setting currently holds. A tab somebody else registered
-- answers for its own; ours are dvars.
-- Which owners' getters take the controller first. Black Ops III's shape is
-- get( dvar, row ) and that is what ZShare, ZPause and ZStats publish on this
-- engine; ZTweaks' takes the Black Ops II shape, get( controller, dvar, row ).
-- A renderer cannot ask a function what it expects, and guessing wrong is not
-- an error -- it is a row that reads empty, shows DEFAULT over a saved value
-- and goes missing from CHANGED.
--
-- `getTakesController` on the registration is the way out of needing to know
-- any of this, and is asked for first. The owner's own name is the fallback,
-- and the published shape is what an owner nobody here has heard of gets.
Z.GET_TAKES_CONTROLLER = {
	ztweaks = true
}

Z.TabGetValue = function ( tab, dvar, row, controller )
	local takes = tab.getTakesController
	if takes == nil then
		takes = Z.GET_TAKES_CONTROLLER[tostring( tab.owner or "" )] == true
	end
	if takes == true then
		return pcall( tab.get, controller or Engine.GetPrimaryController(), dvar, row )
	end
	return pcall( tab.get, dvar, row )
end

Z.RowGet = function ( row, tab, controller )
	if tab ~= nil and type( tab.get ) == "function" then
		local ok, value = Z.TabGetValue( tab, row.dvar, row, controller )
		if ok and value ~= nil then
			return tostring( value )
		end
	end
	return Z.Get( row.dvar )
end

-- An action row is a button: it holds no value, so it reads as empty and
-- counts as at its default -- never in CHANGED, never written by a reset, and
-- its owner's getter is never asked for a setting it does not have. Wrapped
-- around the two rather than written into them, and announced by
-- Z.NativeButtonRowSeam, so a bundle builder that still adds the same guard
-- finds its anchors and can switch to requiring this instead.
Z.NativeButtonRowSeam = 1
do
	local rowGet, isDefault = Z.RowGet, Z.IsDefault
	-- Named locals, so the two definitions above stay the only lines that
	-- spell either header: a builder that patches them counts its anchors.
	local function buttonRead ( row, tab, controller )
		if row ~= nil and row.kind == "button" then
			return ""
		end
		return rowGet( row, tab, controller )
	end
	local function buttonIsDefault ( current, row )
		if row ~= nil and row.kind == "button" then
			return true
		end
		return isDefault( current, row )
	end
	Z.RowGet = buttonRead
	Z.IsDefault = buttonIsDefault
end

-- The one way a value is written, whoever owns it.
Z.Apply = function ( controller, tab, row, value )
	-- Asked again here, not only where the row was built: a component may
	-- give a row an `enabled` callback, and what it answers can change while
	-- the page is open.
	if not Z.Writable( row, tab, controller ) then
		return
	end
	if tab ~= nil and type( tab.set ) == "function" then
		tab.set( controller, row.dvar, value, row )
		return
	end
	-- A tab registered without a set of its own. Its dvar is still the live
	-- value and moving it is what the player asked for, but nothing of
	-- somebody else's goes into ZShare's save record -- a component that
	-- wants its change kept registers a set.
	Z.Set( controller, row.dvar, value, row )
end

-- Called by a row whenever one of its choices is under the cursor: as the
-- page opens, as the cursor moves onto the row, and as left or right moves
-- the choice. Only a move to a different value is a change, so opening a
-- page, scrolling it or hovering a row never writes anything.
-- The choice last put under the cursor on each row, for this session only.
-- A value equal to the row's default reads as DEFAULT everywhere else -- that
-- is what keeps an untouched row saying DEFAULT after a match has written
-- every default into its dvar -- but the selector itself has to stay on the
-- value the player moved to, or a rebuild or a recycled row snaps it back to
-- DEFAULT.
Z.Picked = Z.Picked or {}

Z.PickedKey = function ( row, tab )
	return tostring( tab ~= nil and tab.owner or "" ) .. "|" .. tostring( row.dvar or row.key or "" )
end

-- What was picked, and what the row read straight after the write. The second
-- is what the choice is matched against: an owner may store the default-equal
-- value as empty, or apply it a frame later, and the value picked is then not
-- what reads back.
Z.SetPicked = function ( row, tab, value, observed )
	if row == nil then return end
	Z.Picked[Z.PickedKey( row, tab )] = { value = value, observed = observed }
end

-- Forgotten when the menu opens and on every reset: a new screen, and a row
-- put back to DEFAULT, show DEFAULT again.
Z.ClearPicked = function ()
	Z.Picked = {}
end

-- True when the selector should rest on DEFAULT rather than on the value.
Z.ShowsDefault = function ( current, row, tab )
	local key = Z.PickedKey( row, tab )
	local picked = Z.Picked[key]
	-- The row has moved since, by somebody else or a reset: the pick no longer
	-- describes it, and is dropped whatever the row now reads.
	if picked ~= nil and not ( Z.Same( current, picked.observed ) or Z.Same( current, picked.value ) ) then
		Z.Picked[key] = nil
		picked = nil
	end
	if not Z.IsDefault( current, row ) then
		return false
	end
	if picked == nil then
		return true
	end
	return picked.value == nil or picked.value == ""
end

Z.Chosen = function ( self, element, controller, param, menu )
	local row = param.row or param
	local tab = param.tab
	UpdateInfoModels( element )
	-- Which choice is under the cursor, DEFAULT or a value, so the list that
	-- is built next keeps it there: a value that happens to equal the row's
	-- default would otherwise come back as DEFAULT.
	local picked = element.default == true and "" or element.value
	local current = Z.RowGet( row, tab, controller )
	Z.SetPicked( row, tab, picked, current )
	if element.default == true then
		if Z.IsDefault( current, row ) then
			return
		end
	elseif Z.Same( current, element.value ) then
		return
	end
	Z.Apply( controller, tab, row, element.value )
	Z.SetPicked( row, tab, picked, Z.RowGet( row, tab, controller ) )

	-- A mod switched off on MODS loses its categories there and then, and
	-- one switched back on gets them back. Asked for rather than done here:
	-- the rows this selector sits in are what would be rebuilt underneath it.
	if tab ~= nil and tab.role == "mods" then
		Z.QueueRefreshTabs( menu, controller, tab.id )
		return
	end

	-- Any other change can be the first thing on the screen to differ from a
	-- default, and CHANGED has to become reachable the moment it is. Only when
	-- the answer actually moves, so an ordinary press down a long category is
	-- still one write and nothing else.
	if menu ~= nil then
		local changed = Z.FindTabByRole( menu.zsTabs, "changed" )
		if changed ~= nil then
			local live = Z.TabEnabled( changed, controller )
			if live ~= menu.zsChangedLive then
				menu.zsChangedLive = live
				Z.QueueRefreshTabs( menu, controller, menu.zsTabId )
			end
		end
	end
end

-- One rebuild, after the press that asked for it has finished. A second
-- request before it runs moves the one already queued rather than adding
-- another; a game with no timer to give runs it now, which is still after
-- the callback that asked.
Z.QueueRefreshTabs = function ( menu, controller, preferredId )
	if menu == nil then
		return
	end
	menu.zsPendingController = controller
	menu.zsPendingTabId = preferredId
	if menu.zsRefreshQueued == true then
		return
	end
	menu.zsRefreshQueued = true

	local refresh = function ()
		menu.zsRefreshQueued = nil
		local who = menu.zsPendingController or controller
		local id = menu.zsPendingTabId or preferredId
		menu.zsPendingController = nil
		menu.zsPendingTabId = nil
		Z.RefreshTabs( menu, who, id )
	end

	-- 50ms, not the next frame. A confirmation overlay is still closing when
	-- this is asked for, and on T7x a millisecond is not long enough: the
	-- rebuild lands while the list underneath is occluded and the recycled
	-- selectors keep their pre-reset values until the category is changed.
	local ok, timer = pcall( LUI.UITimer.newElementTimer, 50, true, refresh )
	if ok and timer ~= nil then
		menu:addElement( timer )
	else
		refresh()
	end
end

-- Y, or F on a keyboard: the category with everything at its default taken
-- out of it. For a long category where one setting has been moved and the
-- host wants to see which. Off again on the next press and whenever the
-- category changes, so it is never a page quietly showing half of itself.
--
-- The system categories are left alone: CHANGED is already this, and MODS is
-- four rows.
Z.ToggleChangedFilter = function ( controller, menu )
	if menu == nil or menu.Options == nil then
		return
	end
	local tab = menu.zsTab
	if tab == nil or tab.role ~= nil then
		return
	end
	menu.zsChangedOnly = not menu.zsChangedOnly
	local rows = Z.TabRows( tab )
	if menu.zsChangedOnly then
		local filtered = {}
		for _, row in ipairs( rows ) do
			if not Z.IsDefault( Z.RowGet( row, tab, controller ), row ) then
				table.insert( filtered, row )
			end
		end
		rows = filtered
	end
	menu.zsRows = rows
	Z.BuildRows( menu.zsSource, rows, tab )
	menu.Options:setDataSource( menu.zsSource )
	menu.Subtitle:setText( Z.TabHint( tab )
		.. ( menu.zsChangedOnly and "  " .. Z.Text( "ui.filter_changed_on", "FILTER: CHANGED" ) or "" ) )
	Z.SyncScrollbar( menu )
	if #rows == 0 then
		Z.ShowEmpty( menu )
	end
end

-- The categories as they now stand, for the one page that can change which
-- there are. Every category is given its rows again, since a component coming
-- back has none yet and the MODS page itself has just moved.
--
-- The strip is rebuilt under a name the game has not seen: Black Ops III keeps
-- a grid's item count against its data source's name, so handing back the old
-- name leaves the strip the length it used to be -- a category removed still
-- taking up a cell, or one restored with nowhere to go.
-- Where the list was before a rebuild, and putting it back after one. The
-- grid does keep the selected row itself -- savedActiveIndex, which it writes
-- on every selection -- but not the window that row was sitting in, so a row
-- that was at the top of the viewport came back at the bottom of it.
--
-- The row is remembered by its dvar first and its position second: a rebuild
-- is usually the moment a row appeared or went away, and an index alone would
-- then land on its neighbour.
Z.CaptureView = function ( menu )
	local list = menu ~= nil and menu.Options or nil
	if list == nil then
		return nil
	end
	local active = list.activeWidget
	local index = active ~= nil and active.gridInfoTable ~= nil
		and active.gridInfoTable.zeroBasedIndex or list.savedActiveIndex or 0
	local row = ( menu.zsRows or {} )[index + 1]
	return {
		tabId = menu.zsTabId,
		index = index,
		rowKey = row ~= nil and tostring( row.dvar or "" ) or "",
		first = list.currentStartRow or 1
	}
end

Z.RestoreView = function ( menu, snapshot )
	if snapshot == nil or menu.zsTabId ~= snapshot.tabId or menu.Options == nil then
		return
	end
	local list = menu.Options
	local rows = menu.zsRows or {}
	if #rows == 0 then
		return
	end
	local index = math.min( snapshot.index, #rows - 1 )
	if snapshot.rowKey ~= "" then
		for candidate, row in ipairs( rows ) do
			if tostring( row.dvar or "" ) == snapshot.rowKey then
				index = candidate - 1
				break
			end
		end
	end
	index = math.max( 0, index )
	-- The old top row, held inside the list it now has: not past the last
	-- window a shorter list can show, and never so far from the selected row
	-- that the selection would be off screen.
	local count = math.max( 1, list.vCount or 1 )
	local first = math.max( 1, math.min( snapshot.first, math.max( 1, #rows - count + 1 ) ) )
	first = math.min( first, index + 1 )
	first = math.max( first, index - count + 2 )
	if type( list.updateCurrentPosition ) == "function" then
		list:updateCurrentPosition( first, list.currentStartColumn or 1 )
		list:updateLayout( 0 )
	end
	list:setActiveIndex( index + 1, 1, 0, true )
	if type( list.updateScrollbars ) == "function" then
		list:updateScrollbars()
	end
end

-- The tab strip's window: the start column it had, kept wherever the active
-- category is still inside it, moved just enough to show it otherwise.
Z.TabWindowStart = function ( count, visible, activeIndex, startColumn )
	local first = math.max( 1, math.min( startColumn or 1, math.max( 1, count - visible + 1 ) ) )
	if activeIndex < first then
		first = activeIndex
	elseif activeIndex > first + visible - 1 then
		first = activeIndex - visible + 1
	end
	return first
end

Z.RestoreTabWindow = function ( menu, activeIndex, startColumn )
	local grid = menu ~= nil and menu.Tabs ~= nil and menu.Tabs.grid or nil
	if grid == nil or type( grid.updateCurrentPosition ) ~= "function" then
		return
	end
	local first = Z.TabWindowStart( #( menu.zsTabs or {} ), grid.hCount or 6, activeIndex, startColumn )
	grid:updateCurrentPosition( grid.currentStartRow or 1, first )
	if type( grid.updateLayout ) == "function" then
		grid:updateLayout( 0 )
	end
end

Z.RefreshTabs = function ( menu, controller, preferredId )
	if menu == nil or menu.Tabs == nil or menu.zsMenuName == nil then
		return
	end
	local snapshot = Z.CaptureView( menu )
	local tabs = B.GetTabs( controller )
	local active = Z.FindTab( tabs, preferredId or menu.zsTabId )
	if active ~= nil and not Z.TabEnabled( active, controller ) then
		active = nil
	end
	if active == nil then
		-- Whatever was on screen has just been switched off. Step to the
		-- first category that is still open rather than sitting on a grey one.
		for _, tab in ipairs( tabs ) do
			if Z.TabEnabled( tab, controller ) then
				active = tab
				break
			end
		end
	end
	if active == nil then
		return
	end
	menu.zsTabs = tabs
	for _, tab in ipairs( tabs ) do
		local source = menu.zsSourcePrefix .. tab.id
		menu.zsSources[tab.id] = source
		Z.BuildRows( source, Z.TabRows( tab ), tab )
	end
	-- A mod switched off is still installed and still on the line; one whose
	-- registration has just been corrected is named as it now names itself.
	if menu.ComponentVersions ~= nil then
		menu.ComponentVersions:setText( B.ComponentVersionsText( controller ) )
	end
	if menu.HostBadge ~= nil then
		menu.HostBadge:setText( Z.HostBadgeText( controller ) )
		menu.zsHostStatus = B.HostStatus( controller )
	end
	menu.zsRegistryRevision = ( menu.zsRegistryRevision or 0 ) + 1
	menu.zsTabSource = menu.zsMenuName .. "TabsLive_" .. tostring( menu.zsRegistryRevision )
	Z.BuildTabs( menu.zsTabSource, tabs, active.id, controller )
	-- The strip's window survives the rebuild. setDataSource clears the grid's
	-- layout and puts its start column back to 1, so the active category came
	-- back at whatever edge kept it in view -- one in the third cell jumped to
	-- the sixth when a setting changed (Xep, 14 October 2026). The window the
	-- player was looking at goes back, clamped so the active category is in it.
	local startColumn = menu.Tabs.grid.currentStartColumn or 1
	menu.Tabs.grid:setDataSource( menu.zsTabSource )
	if menu.Tabs.grid.updateDataSource ~= nil then
		menu.Tabs.grid:updateDataSource()
	end
	Z.RestoreTabWindow( menu, Z.FindTabIndex( tabs, active.id ) or 1, startColumn )
	Z.ShowTab( menu, controller, active.id, true )
	Z.UpdateTabNavigation( menu, active.id, controller )
	Z.RestoreView( menu, snapshot )
end

-- The game marks a setting that is not at its default; DEFAULT is the one
-- choice that is.
Z.ShowChange = function ( item )
	return item.default ~= true
end

-- One setting. DEFAULT is the empty value, and it stands for the default
-- itself. A value the page does not step through keeps a choice of its own
-- rather than showing as another.
Z.Row = function ( row, source, tab, controller )
	-- The data source names the controller it is being built for. Only a
	-- caller that has none falls back to the primary one, which is what
	-- every predicate below used to do on its own.
	controller = controller or Engine.GetPrimaryController()
	-- Three states, and the two that are not ordinary are the owner's
	-- doing rather than the menu's: a row the component has switched off,
	-- and one it has pinned to a value for as long as some condition of its
	-- own holds. Both keep their place, their focus and their hover -- the
	-- stock Disabled state would take the last two away with the arrows --
	-- and both say which they are, here and in the panel.
	-- A button is not a setting: no choices, no stored value, one cell saying
	-- what pressing it would do. The cell carries **no action** -- the stock
	-- slider runs ProcessListAction during focus, so anything there fires on
	-- hover -- and keeps `zsOptionLocked`, which is what hides the arrows.
	if row.kind == "button" then
		local hostLocked = B.RowHostLocked( row, tab, controller )
		local available = Z.ButtonAvailable( row, tab, controller )
		DataSources[source] = DataSourceHelpers.ListSetup( source, function ( who )
			who = who or controller
			return { {
				models = {
					text = B.RowHostLocked( row, tab, who )
						and Z.Text( "ui.host_controlled", "HOST CONTROLLED" )
						or ( Z.ButtonAvailable( row, tab, who )
						and Z.Text( "ui.activate", "ACTIVATE" )
						or Z.Text( "ui.unavailable", "UNAVAILABLE" ) ),
					zsOptionLocked = true
				},
				properties = {
					title = row.dvar or "",
					desc = Z.Reason( row, tab, who ),
					selectIndex = true,
					loopEdges = false,
					first = true,
					last = true,
					showChangeIndicator = function ()
						return false
					end
				}
			} }
		end, nil, nil, nil )
		return {
			models = {
				name = Z.RowLabel( row, "ACTION" ),
				dvarText = row.dvar or "",
				desc = Z.Reason( row, tab, controller ),
				defaultCaption = Z.Text( "ui.type", "TYPE" ),
				defaultText = Z.Text( "ui.button", "BUTTON" ),
				boundaryCaption = Z.Text( "ui.status", "STATUS" ),
				boundaryText = hostLocked and Z.Text( "ui.host_controlled", "HOST CONTROLLED" )
					or ( available and Z.Text( "ui.ready", "READY" )
					or Z.Text( "ui.disabled", "DISABLED" ) ),
				scopeText = Z.Keyed( row.scopeKey, row.scope, "LOCAL", Z.OwnerOf( row ), row ),
				zsRowState = available and "NORMAL" or "DISABLED",
				zsButtonRow = true,
				zsUnavailable = not available,
				optionsDatasource = source
			},
			properties = {}
		}
	end

	local forced, locked = Z.Override( row, tab, controller )
	local unavailable = Z.Unavailable( row, tab, controller )
	local hostLocked = B.RowHostLocked( row, tab, controller )
	local state = hostLocked and "HOST"
		or ( locked and "OVERRIDDEN" or ( unavailable and "DISABLED" or "NORMAL" ) )
	-- A locked row shows the owner's value, not the preference underneath
	-- it. Nothing here writes that preference over: the lock is released by
	-- whoever set it, and the saved choice comes back on its own.
	local effective = Z.RowGet( row, tab, controller )
	if locked and forced ~= nil then
		effective = forced
	end

	-- Built fresh for every request. LUIGridLayout takes selectIndex out of
	-- the table it is handed while it prepares a list, so handing the same
	-- table back a second time loses the selected value -- which snapped a
	-- row to DEFAULT as soon as scrolling recycled it.
	local build = function ( who )
		-- The list asks again for each controller it draws for.
		who = who or controller
		local current = Z.RowGet( row, tab, who )
		local atDefault = Z.IsDefault( current, row )
		local listed = atDefault
		for _, value in ipairs( row.values or {} ) do
			if Z.Same( current, value ) then
				listed = true
			end
		end

		local options = {}
		local add = function ( label, value, isDefault, selected )
			table.insert( options, {
				models = {
					text = label
				},
				properties = {
					title = row.dvar or "",
					desc = Z.RowHint( row ),
					value = value,
					default = isDefault,
					actionParam = {
						row = row,
						tab = tab
					},
					action = Z.Chosen,
					selectIndex = selected,
					loopEdges = true,
					showChangeIndicator = Z.ShowChange
				}
			} )
		end

		-- Every value, including the one this build's default happens to
		-- be. It used to be left out, on the grounds that picking it by
		-- value would stop it following the default -- but the row is
		-- built into the mod and the installer's config editor cannot
		-- rewrite it, so once the editor had moved a default the old value
		-- was gone from the page: configure zs_vote on and this offered
		-- DEFAULT (now on) and ON, with no way to turn voting off. DEFAULT
		-- still saves nothing and still follows whatever the script
		-- carries.
		-- Branched before any ordinary choice is built. Skipping a
		-- read-only row only inside reset and randomize is not enough: a
		-- generic list that adds DEFAULT and then the values lets a
		-- compatibility report cycle under the cursor while its setter
		-- quietly does nothing. One freshly built option carrying what the
		-- row currently reads, no action, no change indicator, no looping
		-- at the edges.
		if not Z.Writable( row, tab, who ) then
			-- Asked again rather than taken from the row above: a lock may
			-- have come or gone since, and this is the list the page reads.
			local held, pinned = Z.Override( row, tab, who )
			local value = pinned and held ~= nil and held or current
			local shown = Z.ValueLabel( row, value )
			-- The state in front of the value. The arrows are gone from an
			-- inert row, and a lone value with nothing said about it reads
			-- as a setting that happens to have one choice.
			-- A host-owned row on a client shows neither a state nor a
			-- value: what is in this machine's dvar is this machine's, and
			-- presenting it as the host's live setting is the one thing here
			-- that would read as true and not be.
			if B.RowHostLocked( row, tab, who ) then
				shown = Z.Shell( B.RowHostValue( row, tab, who ) )
			elseif pinned then
				shown = Z.Text( "ui.locked", "LOCKED" ) .. ": " .. shown
			elseif not B.RowEnabled( row, tab, who ) then
				shown = Z.Text( "ui.disabled", "DISABLED" ) .. ": " .. shown
			end
			table.insert( options, {
				models = {
					text = shown,
					zsOptionLocked = true
				},
				properties = {
					title = row.dvar or "",
					desc = Z.Reason( row, tab, who ),
					value = value,
					default = false,
					selectIndex = true,
					loopEdges = false,
					first = true,
					last = true,
					-- The stock slider drops mouse hover on a choice with no
					-- action at all, and hover is how the reason is read. It
					-- does nothing, and never reaches the owner's setter.
					--
					-- **A button row gets none at all.** Stock
					-- ProcessListAction runs during focus, so anything in that
					-- model is dispatched by hovering rather than by pressing --
					-- which is how another mod's destructive action came to fire
					-- on hover in the published bundle. ZShare does not dispatch
					-- button rows at all, and this is the field that would make
					-- a later change to it dangerous rather than inert.
					action = row.kind ~= "button" and function () end or nil
				}
			} )
			return options
		end

		-- A switch says what it is, not what it inherits. ON is a mod's
		-- default, so a DEFAULT choice here reads as ON for a mod that has
		-- just been switched off -- and `zbundle_component_<id>` is a name
		-- for the row rather than a setting anybody writes, so the empty
		-- dvar behind it would select DEFAULT and report every component as
		-- inheriting. Two states, and the live one comes from the
		-- component's own callback through Z.RowGet above.
		if tab ~= nil and tab.role == "mods" then
			add( Z.Text( "ui.on", "ON" ), "1", true, Z.Same( current, "1" ) )
			add( Z.Text( "ui.off", "OFF" ), "0", false, Z.Same( current, "0" ) )
			options[1].properties.first = true
			options[#options].properties.last = true
			return options
		end

		local onDefault = Z.ShowsDefault( current, row, tab )
		add( Z.Text( "ui.default", "DEFAULT" ), "", true, onDefault )
		for index, value in ipairs( row.values or {} ) do
			if not listed and row.kind == "number" and tonumber( current ) ~= nil and tonumber( current ) < tonumber( value ) then
				add( current, current, false, true )
				listed = true
			end
			add( Z.ChoiceLabel( row, index, value ), value, false, not onDefault and Z.Same( current, value ) )
		end
		if not listed then
			add( string.upper( current ), current, false, true )
		end
		options[1].properties.first = true
		options[#options].properties.last = true
		return options
	end

	DataSources[source] = DataSourceHelpers.ListSetup( source, build, nil, nil, nil )
	-- DEFAULT / APPLIES are what an ordinary row's panel is captioned.
	-- A row that cannot be written has no default worth naming -- what it
	-- is now, and why, is the whole of what a player needs -- so the two
	-- captions change with it. SCOPE keeps its own meaning throughout.
	-- Written on every row, NORMAL included: these models are what clears
	-- the state again when a recycled widget is handed an editable row.
	return {
		models = {
			name = Z.RowLabel( row ),
			dvarText = row.dvar or "",
			desc = state == "NORMAL" and Z.Reason( row, tab, controller )
				or ( Z.StateText( state ) .. ": " .. Z.Reason( row, tab, controller ) ),
			defaultText = state == "NORMAL" and Z.DefaultLabel( row )
				or ( state == "HOST" and Z.Shell( B.RowHostValue( row, tab, controller ) ) or Z.ValueLabel( row, effective ) ),
			defaultCaption = state == "OVERRIDDEN" and Z.Text( "ui.forced", "FORCED" )
				or ( ( state == "DISABLED" or state == "HOST" ) and Z.Text( "ui.current", "CURRENT" )
				or Z.Text( "ui.default", "DEFAULT" ) ),
			boundaryText = state == "NORMAL" and Z.Boundary( row )
				or ( state == "HOST" and Z.Text( "ui.host_controlled", "HOST CONTROLLED" ) or Z.StateText( state ) ),
			boundaryCaption = state == "NORMAL" and Z.Text( "ui.applies", "APPLIES" )
				or Z.Text( "ui.status", "STATUS" ),
			scopeText = Z.Scope( row ),
			zsRowState = state,
			zsUnavailable = unavailable,
			optionsDatasource = source
		},
		properties = {}
	}
end

-- One outer data source per tab, never one shared between them: T7x keeps a
-- data source alive past the menu that made it, so a shorter tab reusing a
-- longer one's source inherits its row count and shows a scrollbar for rows
-- that are not there.
Z.BuildRows = function ( name, rows, tab )
	-- The stock list hands its builder the controller it is drawing for, and
	-- it is handed on: a row's availability, its reason and the value it
	-- shows are all answers about a player, and a second controller asking
	-- used to get the first one's.
	DataSources[name] = DataSourceHelpers.ListSetup( name, function ( controller )
		local items = {}
		for index, row in ipairs( rows ) do
			table.insert( items, Z.Row( row, name .. "_" .. index, tab, controller ) )
		end
		return items
	end, nil, nil, nil )
end

Z.BuildTabs = function ( name, tabs, selected, controller )
	DataSources[name] = DataSourceHelpers.ListSetup( name, function ()
		local items = {}
		for _, tab in ipairs( tabs ) do
			table.insert( items, {
				models = {
					tabName = Z.TabLabel( tab ),
					tabId = tab.id,
					tabHint = Z.TabHint( tab ),
					tabOwner = tab.owner or "",
					disabled = not Z.TabEnabled( tab, controller )
				},
				properties = {
					selectIndex = tab.id == selected
				}
			} )
		end
		return items
	end, nil, nil, nil )
end

-- The stock scrollbar caches the height it was built with, and a data source
-- outlives the menu that made it on T7x, so a longer tab could leave a
-- misleading thumb behind on a shorter one. Both are told the truth again
-- every time a tab is shown.
Z.SyncScrollbar = function ( menu )
	if menu == nil or menu.Options == nil then
		return
	end
	menu.Options.vCount = 7
	menu.Options.requestedRowCount = #menu.zsRows
	if menu.Options.verticalScrollbar ~= nil then
		local _, height = menu.Options:getLocalSize()
		if height ~= nil and height > 24 then
			menu.Options.verticalScrollbar.sliderTop = 12
			menu.Options.verticalScrollbar.sliderHeight = height - 24
		end
	end
	menu.Options:updateScrollbars()
end

-- What lies either side of the tab under the cursor, and where it is in the
-- run. Six cells are visible at a time and there can be more than six tabs,
-- so without this a player has no way of knowing the rest are there.
Z.UpdateTabNavigation = function ( menu, id, controller )
	if menu == nil or menu.zsTabs == nil then
		return
	end
	local count = #menu.zsTabs
	local index = Z.FindTabIndex( menu.zsTabs, id )
	-- Where the arrows actually go, which is not always the cell next door:
	-- a switched-off mod's categories sit on the strip greyed and are
	-- stepped over, so naming the neighbour would name somewhere the press
	-- does not lead.
	local previous = Z.AdjacentTabIndex( menu, controller, -1 )
	local following = Z.AdjacentTabIndex( menu, controller, 1 )
	-- Both wrap, so these dim only when there is no second category to be
	-- in -- a bundle whose other mods are all switched off, or a build with
	-- one category of its own.
	if menu.TabLeft ~= nil then
		menu.TabLeft:setAlpha( previous ~= nil and 1 or 0.22 )
	end
	if menu.TabRight ~= nil then
		menu.TabRight:setAlpha( following ~= nil and 1 or 0.22 )
	end
	if menu.TabPrevious ~= nil then
		menu.TabPrevious:setText( previous ~= nil
			and "<  " .. Z.Text( "ui.prev", "PREV" ) .. ": " .. Z.TabLabel( menu.zsTabs[previous] )
			or "" )
	end
	if menu.TabNext ~= nil then
		menu.TabNext:setText( following ~= nil
			and Z.Text( "ui.next", "NEXT" ) .. ": " .. Z.TabLabel( menu.zsTabs[following] ) .. "  >"
			or "" )
	end
	if menu.TabPosition ~= nil then
		menu.TabPosition:setText( Z.Text( "ui.category", "CATEGORY" ) .. " "
			.. tostring( index ) .. " / " .. tostring( count ) )
	end
end

-- A tab with nothing in it. The details panel is linked to the list's
-- selected row, and an empty list selects nothing, so it would otherwise
-- keep the last row of the tab you just left.
Z.ShowEmpty = function ( menu )
	if menu.DetailsTitle ~= nil then
		menu.DetailsTitle:setText( Z.Text( "ui.no_settings", "NO SETTINGS" ) )
	end
	-- Including the captions, which a row may have renamed on the way here.
	if menu.DefaultLabel ~= nil then
		menu.DefaultLabel:setText( Z.Text( "ui.default", "DEFAULT" ) )
	end
	if menu.AppliesLabel ~= nil then
		menu.AppliesLabel:setText( Z.Text( "ui.applies", "APPLIES" ) )
	end
	for _, element in ipairs( {
		menu.DetailsDvar,
		menu.DetailsDescription,
		menu.DetailsDefault,
		menu.DetailsBoundary,
		menu.DetailsScope
	} ) do
		if element ~= nil then
			element:setText( "" )
		end
	end
end

-- Moving to a tab keeps where the cursor was on the one being left, so
-- stepping across the tabs and back does not lose your place.
Z.ShowTab = function ( menu, controller, id, force )
	if menu == nil or menu.Options == nil or id == nil then
		return
	end
	-- Moving to the category already on screen is nothing, unless the rows
	-- under it have just been rebuilt.
	if id == menu.zsTabId and force ~= true then
		return
	end
	local tab = Z.FindTab( menu.zsTabs, id )
	if tab == nil or not Z.TabEnabled( tab, controller ) then
		return
	end
	if menu.zsTabId ~= nil then
		menu.zsTabAt[menu.zsTabId] = menu.Options.savedActiveIndex or 0
	end
	menu.zsTabId = id
	menu.zsTab = tab
	menu.zsChangedOnly = false
	menu.zsSource = menu.zsSources[id]
	menu.zsRows = Z.TabRows( tab )
	-- Rebuilt rather than reused: a tab whose rows are a function -- a
	-- report, or another mod's changed list -- answers differently each
	-- time it is asked.
	Z.BuildRows( menu.zsSource, menu.zsRows, tab )
	if menu.Title ~= nil then
		menu.Title:setText( Z.TabTitle( tab, menu.zsTabs ) )
	end
	menu.Subtitle:setText( Z.SubtitleText( tab ) )
	menu.Options.savedActiveIndex = menu.zsTabAt[id] or 0
	menu.Options:setDataSource( menu.zsSource )
	Z.SyncScrollbar( menu )
	Z.UpdateTabNavigation( menu, id, controller )
	if #menu.zsRows == 0 then
		Z.ShowEmpty( menu )
	end
end

-- ------------------------------------------------------------------------
-- Reset and randomize
-- ------------------------------------------------------------------------

-- Every registered tab's own save, ours included. Called once when the page
-- closes and again after a bulk action, so a crash between the two leaves the
-- change on disk rather than only in the dvars.
Z.FlushTabs = function ( controller )
	Z.Flush( controller )
	for _, tab in ipairs( B.GetTabs( controller ) ) do
		if type( tab.flush ) == "function" then
			pcall( tab.flush, controller, tab )
		end
	end
end

-- A reset is a transaction, and the shape of it is the shell handoff's:
-- every row in the batch written through its own tab's `set`, each owner
-- flushed once at the end, and one rebuild after all of it -- queued, so it
-- lands after the confirmation overlay has begun closing rather than behind
-- it.
--
-- What is written is the row's own declared default, never an empty value.
-- An empty dvar is whatever the engine registered the name with, which is
-- not always what the menu calls DEFAULT, and a row can end up on CHANGED
-- while its own selector reads DEFAULT.
Z.Editable = function ( tab, controller )
	local rows = {}
	for _, row in ipairs( Z.TabRows( tab ) ) do
		-- A row with no name to write is not one a bulk action can touch
		-- either, whatever else it says about itself.
		if Z.Writable( row, tab, controller )
			and row.dvar ~= nil and row.dvar ~= "" then
			table.insert( rows, row )
		end
	end
	return rows
end

Z.ResetRows = function ( controller, menu, tabs )
	Z.ClearPicked()
	local flushed = {}
	local order = {}
	local done = {}
	local fallback = {}
	local fallbackOrder = {}
	for _, tab in ipairs( tabs ) do
		for _, row in ipairs( Z.Editable( tab, controller ) ) do
			local key = tostring( tab.owner ) .. "|" .. tostring( row.dvar )
			if not done[key] then
				done[key] = true
				Z.Apply( controller, tab, row, row.default or "" )
			end
		end
		-- Whether this owner's whole-store reset is still eligible is a
		-- question about the owner across the whole batch, not about one tab:
		-- a setter anywhere means its rows are writable the ordinary way, and
		-- a row refused anywhere -- read-only, disabled, locked, the host's --
		-- means the batch did not reset everything it was looking at, so
		-- clearing the owner's whole store would go further than the player
		-- asked. Gathered here and decided after every row has been written.
		local owner = tostring( tab.owner )
		local state = fallback[owner]
		if state == nil then
			state = {
				setter = false,
				blocked = false,
				reset = nil,
				tab = nil
			}
			fallback[owner] = state
			table.insert( fallbackOrder, owner )
		end
		if type( tab.set ) == "function" then
			state.setter = true
		end
		if state.reset == nil and type( tab.reset ) == "function" then
			state.reset = tab.reset
			state.tab = tab
		end
		for _, row in ipairs( Z.TabRows( tab ) ) do
			-- A button is never part of a bulk edit and is not a refusal.
			if row.kind ~= "button" and row.dvar ~= nil and row.dvar ~= ""
				and not B.RowWritable( row, tab, controller ) then
				state.blocked = true
			end
		end
		if type( tab.flush ) == "function" and not flushed[tab.owner] then
			flushed[tab.owner] = true
			table.insert( order, tab )
		end
	end
	-- The owner-wide reset, for an owner that offered no way to write a row
	-- and had nothing refused. Only for a host: it can clear settings this
	-- page never showed, so a client reaching it would be resetting the
	-- host's mod through a tab of their own.
	if B.HostStatus( controller ) == "HOST" then
		for _, owner in ipairs( fallbackOrder ) do
			local state = fallback[owner]
			if state.reset ~= nil and not state.setter and not state.blocked then
				pcall( state.reset, controller, nil, state.tab )
			end
		end
	end

	-- ZShare's own record, then once per owner that asked to be flushed.
	Z.Flush( controller )
	for _, tab in ipairs( order ) do
		pcall( tab.flush, controller, tab )
	end
	-- One rebuild, after the batch and after the overlay.
	Z.QueueRefreshTabs( menu, controller, menu ~= nil and menu.zsTabId or nil )
end

-- Every editable category on the screen, whoever registered it. RESET ALL
-- says every setting, and on a bundle that is every mod's -- the aggregate
-- the shell handoff asks for, not just the owner whose category is open.
Z.ResetAll = function ( controller, menu )
	Z.ClearPicked()
	Z.ResetRows( controller, menu, B.GetTabs( controller ) )
end

-- Kept for the registry, which hands it to whoever draws the screen: every
-- category ZShare owns, for a shell with no row setter to call.
Z.ResetOwner = function ( controller, menu )
	local mine = {}
	for _, tab in ipairs( B.GetTabs( controller ) ) do
		if tab.owner == Z.Owner then
			table.insert( mine, tab )
		end
	end
	Z.ResetRows( controller, menu, mine )
end

Z.ResetTab = function ( controller, menu )
	local tab = menu ~= nil and menu.zsTab or nil
	if tab == nil then
		return
	end
	Z.ResetRows( controller, menu, { tab } )
end

Z.RandomizeTab = function ( controller, menu )
	Z.ClearPicked()
	local tab = menu ~= nil and menu.zsTab or nil
	if tab == nil then
		return
	end
	for _, row in ipairs( Z.Editable( tab, controller ) ) do
		-- The row's default is one of the choices. A randomize that could
		-- only ever pick something else would leave a page there was no way
		-- back from except resetting it by hand.
		local choices = {
			row.default or ""
		}
		for _, value in ipairs( row.values or {} ) do
			if not Z.Same( value, row.default ) then
				table.insert( choices, value )
			end
		end
		Z.Apply( controller, tab, row, choices[math.random( #choices )] )
	end
	-- This category's owner, and nobody else's: flushing every registered
	-- tab would be ZShare writing another component's store because a page
	-- of its own was randomized.
	if tab.owner == Z.Owner then
		Z.Flush( controller )
	end
	if type( tab.flush ) == "function" then
		pcall( tab.flush, controller, tab )
	end
	Z.QueueRefreshTabs( menu, controller, menu.zsTabId )
end

Z.Ask = function ( controller, settings, name, title, description, confirmed )
	CoD.OverlayUtility.AddSystemOverlay( name, {
		menuName = "SystemOverlay_Compact",
		title = title,
		description = description,
		categoryType = CoD.OverlayUtility.OverlayTypes.Alert,
		listDatasource = function ()
			DataSources[name .. "_List"] = DataSourceHelpers.ListSetup( name .. "_List", function ()
				return {
					{
						models = {
							displayText = Engine.Localize( "MENU_NO" )
						},
						properties = {
							action = function ( self, element, choiceController, param, menu )
								GoBack( menu, choiceController )
							end
						}
					},
					{
						models = {
							displayText = Engine.Localize( "MENU_YES" )
						},
						properties = {
							action = function ( self, element, choiceController, param, menu )
								-- Close first. A rebuild asked for while this
								-- overlay still covers the page leaves the
								-- rows it rebuilt behind it.
								GoBack( menu, choiceController )
								confirmed( choiceController, settings )
							end
						}
					}
				}
			end, true, nil )
			return name .. "_List"
		end
	} )
	CoD.OverlayUtility.CreateOverlay( controller, settings, name )
end

Z.AskResetTab = function ( controller, settings )
	Z.Ask( controller, settings, "ZShareSettingsResetTab",
		Z.Text( "ui.reset_tab", "RESET TAB" ),
		Z.Text( "ui.reset_tab_ask", "Put every setting on this tab back to its default?" ),
		Z.ResetTab )
end

Z.AskRandomize = function ( controller, settings )
	Z.Ask( controller, settings, "ZShareSettingsRandomize",
		Z.Text( "ui.randomize", "RANDOMIZE" ),
		Z.Text( "ui.randomize_ask",
			"Choose a random value for every setting on this tab? DEFAULT is one of them." ),
		Z.RandomizeTab )
end

Z.AskReset = function ( controller, settings )
	local tab = settings ~= nil and settings.zsTab or nil
	local ask = Z.Text( "ui.reset_ask", "Put every ZShare setting back to its default?" )
	if tab ~= nil and tab.owner ~= Z.Owner then
		ask = Z.Text( "ui.reset_owner_ask",
			"Put every setting this mod owns back to its default?" )
	end
	Z.Ask( controller, settings, "ZShareSettingsReset",
		Z.Text( "ui.reset", "RESET TO DEFAULTS" ), ask, Z.ResetOwner )
end

Z.Back = function ( menu, controller )
	Z.StopTabHold( menu )
	Z.FlushTabs( controller )
	GoBack( menu, controller )
	ClearSavedState( menu, controller )
end

-- ------------------------------------------------------------------------
-- The one builder, for both ways in
-- ------------------------------------------------------------------------

-- Does somebody else own the visible settings screen?
--
-- The whole of ZShare's stand-down under the bundle-entry contract. The shared menu kit installs
-- its entry factory as a versioned in-place upgrade and the winner sets B.MenuEntry; a loser asks
-- one question - is there a handle, and is it not mine - and sends the player there instead of
-- building a second screen.
--
-- **ZShare publishes no SharedMenuKitVersion**, deliberately: it carries no kit, and a version
-- claimed with nothing behind it is the empty-CHANGED defect in a new place. This is the asking
-- half only, and it changes nothing until some other owner sets B.MenuEntry.
--
-- **It fails OPEN.** No handle, or a handle that is not a function, and ZShare builds its own
-- screen exactly as it does today. A claim made half way must not leave a dead button: the lobby
-- button and the pause-menu row stay visible either way, and a player pressing one and getting
-- nothing is a worse regression than anything the kit fixes.
Z.MenuEntryElsewhere = function ( mine )
	-- `mine` defaults to ZShare's own handle rather than relying on every call site to pass it.
	-- A call site that forgets has nothing to tell its own handle from somebody else's, which is
	-- the self-delegating recursion with the guard absent rather than present. Z.MenuEntry is
	-- deliberately nil today -- ZShare sets no B.MenuEntry and so can never be the winner -- so
	-- this changes nothing now and protects a future ZShare that does claim the entry.
	mine = mine or Z.MenuEntry
	local entry = B.MenuEntry
	if type( entry ) ~= "function" then
		return nil
	end
	if mine ~= nil and entry == mine then
		return nil
	end
	return entry
end

Z.CreateMenu = function ( controller, menuName )
	-- A new screen shows DEFAULT again wherever a row is at its default.
	Z.ClearPicked()
	-- Rule 3: a losing owner stands its RUNTIME down, not just its drawing. Returning here is the
	-- whole of it, because every timer, every tab hold-repeat and every button callback in this
	-- file attaches to a menu object -- so none of them is ever created, and there is no teardown
	-- list to keep in step with the next timer somebody adds.
	--
	-- Both ways in come through here, the lobby's LUI.createMenu.ZShareSettings and the pause
	-- menu's ZShareInGameSettings, so one check covers both routes and neither has a second path.
	--
	-- ZShare's storage keeper is untouched, and that is rule 4 rather than luck: Z.Hook and Z.Wait
	-- run at file scope when this file is read, not from a menu, so a delegated screen still keeps
	-- and restores ZShare's settings. Z.Startup also runs in Z.OpenFromPause before the popup is
	-- opened, which is ahead of this check either way.
	local elsewhere = Z.MenuEntryElsewhere( Z.MenuEntry )
	if elsewhere ~= nil then
		return elsewhere( controller )
	end

	require( "ui.uieditor.widgets.StartMenu.StartMenu_Options_Slider_Small" )
	require( "ui.uieditor.widgets.StartMenu.StartMenu_Options_Slider_Control_Item_Small" )
	require( "ui.uieditor.widgets.Lobby.Common.List1ButtonLarge_PH" )
	require( "ui.uieditor.widgets.TabbedWidgets.basicTabList" )
	require( "ui.uieditor.widgets.TabbedWidgets.paintshopTabWidget" )
	require( "ui.uieditor.widgets.BumperButtonWithKeyMouse" )
	require( "ui.uieditor.widgets.Scrollbars.verticalScrollbar" )
	Z.InstallHeldShortcutBitGuard()

	-- The stock slider makes its arrows clickable but leaves the value text
	-- inert, and the text is the part a mouse goes for. TextBox belongs to
	-- the inner control item rather than to the slider, so the click target
	-- goes there; loopEdges on the rows brings the last value round to
	-- DEFAULT again.
	if CoD.ZShare_Options_Slider_Control_Item_Small == nil then
		CoD.ZShare_Options_Slider_Control_Item_Small = InheritFrom( CoD.StartMenu_Options_Slider_Control_Item_Small )
		CoD.ZShare_Options_Slider_Control_Item_Small.new = function ( owner, ownerController )
			local widget = CoD.StartMenu_Options_Slider_Control_Item_Small.new( owner, ownerController )
			widget:setClass( CoD.ZShare_Options_Slider_Control_Item_Small )
			widget:setLeftRight( true, false, 0, 215 )

			-- An inert row loses its arrows and keeps everything else. The
			-- alpha is clamped rather than set once because the focus clip
			-- draws them again every time it runs, hover included, and the
			-- state is forced for the same reason.
			for _, arrow in ipairs( { widget.left, widget.right } ) do
				for _, part in ipairs( { arrow, arrow.arrow } ) do
					local inherited = part.setAlpha
					part.setAlpha = function ( element, alpha, ... )
						return inherited( element, widget.zsOptionLocked and 0 or alpha, ... )
					end
				end
			end
			local inheritedState = widget.setState
			widget.setState = function ( element, state, ... )
				if element.zsOptionLocked then
					state = "ArrowsHidden"
				end
				return inheritedState( element, state, ... )
			end
			local applyLock = function ( locked )
				if widget.zsOptionLocked == locked then
					return
				end
				widget.zsOptionLocked = locked
				widget:setState( locked and "ArrowsHidden" or "DefaultState" )
				widget.left:setAlpha( locked and 0 or 1 )
				widget.left.arrow:setAlpha( locked and 0 or 1 )
				widget.right:setAlpha( locked and 0 or 1 )
				widget.right.arrow:setAlpha( locked and 0 or 1 )
				widget.left:setHandleMouse( not locked )
				widget.right:setHandleMouse( not locked )
			end
			widget:linkToElementModel( widget, "zsOptionLocked", true, function ( model )
				local value = Engine.GetModelValue( model )
				applyLock( value == true or value == 1 or value == "1" or value == "true" )
			end )
			-- The lock model is only written on a row that has one, and a
			-- recycled widget keeps what the row before it had -- so the
			-- text, which every row writes, is what takes it off again.
			widget:linkToElementModel( widget, "text", true, function ( textModel )
				local model = widget:getModel( ownerController, "zsOptionLocked" )
				local value = model ~= nil and Engine.GetModelValue( model ) or nil
				local text = tostring( Engine.GetModelValue( textModel ) or "" )
				applyLock( value == true or value == 1 or value == "1" or value == "true"
					or string.find( text, "^DISABLED: " ) ~= nil or string.find( text, "^LOCKED: " ) ~= nil )
			end )

			widget.TextBox:setHandleMouse( true )
			widget.TextBox:registerEventHandler( "button_action", function ()
				-- The widget itself is handed over, so the press is resolved
				-- from the row that was clicked rather than the row that
				-- happens to have focus.
				if Z.ButtonRowAt( owner, ownerController, widget ) then
					return true
				end
				SendButtonPressToMenuEx( owner, ownerController, Enum.LUIButton.LUI_KEY_RIGHT )
				return true
			end )
			return widget
		end
	end
	if CoD.ZShare_Options_Slider_Small == nil then
		CoD.ZShare_Options_Slider_Small = InheritFrom( CoD.StartMenu_Options_Slider_Small )
		CoD.ZShare_Options_Slider_Small.new = function ( owner, ownerController )
			local widget = CoD.StartMenu_Options_Slider_Small.new( owner, ownerController )
			widget:setClass( CoD.ZShare_Options_Slider_Small )
			-- The last 20 of the list's 520 units are its scrollbar. What
			-- is left is halved between the name and its value, and the
			-- value control is widened so its arrows reach both edges.
			widget:setLeftRight( true, false, 0, 500 )
			widget.StartMenuframenoBG0:setLeftRight( true, true, 0, -254 )
			widget.StartMenuframenoBG1:setLeftRight( true, true, 254, -1 )
			widget.Title:setLeftRight( true, false, 20, 230 )
			widget.Slider:setLeftRight( true, false, 270, 485 )
			widget.altText:setLeftRight( true, false, 254, 499 )
			widget.FocusBarB:setLeftRight( true, true, 254, -2 )
			widget.FocusBarT:setLeftRight( true, true, 254, -2 )
			widget.Slider:setWidgetType( CoD.ZShare_Options_Slider_Control_Item_Small )

			-- A row on CHANGED carries its owner's name in front of the
			-- setting's and can outrun the name column. The text takes its
			-- size from the height of the element it is in, so a long one
			-- is given a shorter element -- and the row itself is left
			-- alone, since rows of different heights break the fixed
			-- viewport, the scrollbar's arithmetic and widget recycling.
			-- Written as a subscription rather than once, because that is
			-- also what puts the stock size back when a recycled widget is
			-- handed a shorter name.
			widget.Title:linkToElementModel( widget, "name", true, function ( model )
				local value = Engine.GetModelValue( model )
				local name = value ~= nil and Engine.Localize( value ) or ""
				local half = #name > 27 and 8.5 or 11
				widget.Title:setTopBottom( false, false, -half, half )
			end )

			-- Grey for a row the owner has switched off, amber for one it has
			-- pinned, and the ordinary white otherwise. Put back after every
			-- stock clip transition, which restores the normal opacity on its
			-- own, and cleared when a recycled widget takes an editable row.
			local applyState = function ()
				local state = widget.zsRowState
				widget:setAlpha( state == "DISABLED" and 0.52 or ( state == "OVERRIDDEN" and 0.72 or 1 ) )
				if state == "DISABLED" then
					widget.Title:setRGB( 0.68, 0.68, 0.68 )
				elseif state == "OVERRIDDEN" then
					widget.Title:setRGB( 1, 0.7, 0.4 )
				else
					widget.Title:setRGB( 1, 1, 1 )
				end
			end
			widget:linkToElementModel( widget, "zsRowState", true, function ( model )
				widget.zsRowState = Engine.GetModelValue( model )
				applyState()
			end )
			LUI.OverrideFunction_CallOriginalSecond( widget, "setState", applyState )

			return widget
		end
	end
	if CoD.ZShare_TabWidget == nil then
		CoD.ZShare_TabWidget = InheritFrom( CoD.paintshopTabWidget )
		CoD.ZShare_TabWidget.new = function ( owner, ownerController )
			local widget = CoD.paintshopTabWidget.new( owner, ownerController )
			widget:setClass( CoD.ZShare_TabWidget )
			-- Six cells and the five native two-unit gaps between them fill
			-- the 1010-unit strip exactly: (1010 - 5 * 2) / 6. Do not
			-- centre this with a firstElementXOffset instead -- BO3 then
			-- counts the incoming seventh cell as partly visible and will
			-- move the selection onto a tab that is still outside the
			-- stencil, so the page changes under a highlight nobody can
			-- see.
			widget.getWidthInList = function ()
				return 500 / 3
			end
			return widget
		end
	end

	-- Every tab anybody has registered, ZShare's among them, in the order
	-- the registry gives. One data source per tab, named for its id.
	local tabs = B.GetTabs( controller )
	-- The first category that can actually be walked into. A switched-off
	-- mod's categories are on the strip now rather than gone, so the first
	-- of them is no longer necessarily one to open on.
	local first = tabs[1]
	for _, tab in ipairs( tabs ) do
		if Z.TabEnabled( tab, controller ) then
			first = tab
			break
		end
	end
	local sources = {}
	for _, tab in ipairs( tabs ) do
		sources[tab.id] = menuName .. "Rows_" .. tab.id
		Z.BuildRows( sources[tab.id], Z.TabRows( tab ), tab )
	end
	local tabSource = menuName .. "Tabs"
	Z.BuildTabs( tabSource, tabs, first.id, controller )
	-- What CHANGED looked like when the page opened, so the first edit that
	-- moves it is the only one that rebuilds the strip.
	local changedAtOpen = Z.FindTabByRole( tabs, "changed" )
	changedAtOpen = changedAtOpen ~= nil and Z.TabEnabled( changedAtOpen, controller ) or false
	local sourcePrefix = menuName .. "Rows_"

	local self = CoD.Menu.NewForUIEditor( menuName )
	self.zsChangedLive = changedAtOpen
	self.disablePopupOpenCloseAnim = true
	self.soundSet = "ChooseDecal"
	self:setOwner( controller )
	self:setLeftRight( true, true, 0, 0 )
	self:setTopBottom( true, true, 0, 0 )
	self:playSound( "menu_open", controller )
	self.buttonModel = Engine.CreateModel( Engine.GetModelForController( controller ), menuName .. ".buttonPrompts" )
	self.anyChildUsesUpdateState = true
	self.zsTabs = tabs
	self.zsTab = first
	self.zsTabId = first.id
	self.zsSources = sources
