		left = Randomize
	}
	CoD.Menu.AddNavigationHandler( self, self, controller )

	-- A footer button takes the same press the list does, so each one keeps
	-- the focus handlers the prompt is drawn from.
	local footer = function ( button, action )
		button:registerEventHandler( "gain_focus", function ( element, event )
			local result = nil
			if element.gainFocus then
				result = element:gainFocus( event )
			elseif element.super.gainFocus then
				result = element.super:gainFocus( event )
			end
			CoD.Menu.UpdateButtonShownState( element, self, controller, Enum.LUIButton.LUI_KEY_XBA_PSCROSS )
			return result
		end )
		button:registerEventHandler( "lose_focus", function ( element, event )
			if element.loseFocus then
				return element:loseFocus( event )
			elseif element.super.loseFocus then
				return element.super:loseFocus( event )
			end
		end )
		self:AddButtonCallbackFunction( button, controller, Enum.LUIButton.LUI_KEY_XBA_PSCROSS, "ENTER", function ()
			action()
			return true
		end, function ( element, menu )
			CoD.Menu.SetButtonLabel( menu, Enum.LUIButton.LUI_KEY_XBA_PSCROSS, "MENU_SELECT" )
			return true
		end, false )
	end
	footer( Reset, function ()
		Z.AskResetTab( controller, self )
	end )
	footer( Randomize, function ()
		Z.AskRandomize( controller, self )
	end )
	footer( ResetAll, function ()
		Z.AskReset( controller, self )
	end )
	footer( Back, function ()
		Z.Back( self, controller )
	end )

	self:AddButtonCallbackFunction( self, controller, Enum.LUIButton.LUI_KEY_XBB_PSCIRCLE, nil, function ()
		Z.Back( self, controller )
		return true
	end, function ( element, menu )
		CoD.Menu.SetButtonLabel( menu, Enum.LUIButton.LUI_KEY_XBB_PSCIRCLE, "MENU_BACK" )
		return true
	end, false )
	self:AddButtonCallbackFunction( self, controller, Enum.LUIButton.LUI_KEY_XBX_PSSQUARE, "R", function ()
		Z.AskReset( controller, self )
		return true
	end, function ( element, menu )
		CoD.Menu.SetButtonLabel( menu, Enum.LUIButton.LUI_KEY_XBX_PSSQUARE, Z.Text( "ui.reset", "RESET TO DEFAULTS" ) )
		return true
	end, false )
	self:AddButtonCallbackFunction( self, controller, Enum.LUIButton.LUI_KEY_XBY_PSTRIANGLE, "F", function ()
		Z.ToggleChangedFilter( controller, self )
		return true
	end, function ( element, menu )
		CoD.Menu.SetButtonLabel( menu, Enum.LUIButton.LUI_KEY_XBY_PSTRIANGLE,
			Z.Text( "ui.filter_changed", "FILTER CHANGED" ) )
		return true
	end, false )
	-- Enter and A on the focused row. Registered on the menu rather than on a
	-- footer button, which is where ZShare's other confirm binding lives, so
	-- neither replaces the other -- the stock registration overwrites by
	-- element and key.
	--
	-- On the menu itself and not only in LUI.createMenu, because the pause
	-- route calls Z.CreateMenu directly and would otherwise have no dispatch.
	self:AddButtonCallbackFunction( self, controller, Enum.LUIButton.LUI_KEY_XBA_PSCROSS, "ENTER", function ()
		return Z.ButtonRowAt( self, controller )
	end, function ( element, menu )
		CoD.Menu.SetButtonLabel( menu, Enum.LUIButton.LUI_KEY_XBA_PSCROSS, "MENU_SELECT" )
		return true
	end, false )
	-- Registered so the engine creates and publishes the bumper and Q/E
	-- models, and inert: Z.AttachTabHold steps the strip on the edge, and a
	-- callback that also stepped would be a second step.
	self:AddButtonCallbackFunction( self, controller, Enum.LUIButton.LUI_KEY_LB, "Q", function ()
		return true
	end, AlwaysFalse, false )
	self:AddButtonCallbackFunction( self, controller, Enum.LUIButton.LUI_KEY_RB, "E", function ()
		return true
	end, AlwaysFalse, false )
	-- Hold the bumpers or Q/E to keep moving, the arrows to keep moving.
	Z.AttachTabHold( self, controller )
	-- The page can also be left without going through Z.Back -- the pause
	-- menu's popup route closes it outright -- and a timer outliving the
	-- menu it steps is a timer stepping nothing.
	LUI.OverrideFunction_CallOriginalSecond( self, "close", function ( element )
		Z.StopTabHold( element )
	end )

	self:processEvent( {
		name = "menu_loaded",
		controller = controller
	} )
	self:processEvent( {
		name = "update_state",
		menu = self
	} )
	Z.SyncScrollbar( self )
	if #self.zsRows == 0 then
		Z.ShowEmpty( self )
	end

	-- Host status is not fixed while the page is open: a migration hands it
	-- over, and every row's writability goes with it. Watched rather than
	-- read once at construction, and only a change costs a rebuild.
	self.zsHostStatus = B.HostStatus( controller )
	self:addElement( LUI.UITimer.newElementTimer( 1000, false, function ()
		local status = B.HostStatus( controller )
		if status == self.zsHostStatus then
			return
		end
		self.zsHostStatus = status
		if self.HostBadge ~= nil then
			self.HostBadge:setText( Z.HostBadgeText( controller ) )
		end
		Z.QueueRefreshTabs( self, controller, self.zsTabId )
	end ) )
	if not self:restoreState() then
		Options:processEvent( {
			name = "gain_focus",
			controller = controller
		} )
	end
	LUI.OverrideFunction_CallOriginalSecond( self, "close", function ( element )
		Z.FlushTabs( controller )
		element.Options:close()
		element.Back:close()
		element.Reset:close()
		element.Randomize:close()
		element.ResetAll:close()
		element.DetailsScope:close()
		element.ScopeLabel:close()
		element.DetailsBoundary:close()
		element.AppliesLabel:close()
		element.DetailsDefault:close()
		element.DefaultLabel:close()
		element.DetailsDescription:close()
		element.DescriptionLabel:close()
		element.DetailsDvar:close()
		element.DetailsTitle:close()
		element.DetailsAccent:close()
		element.Details:close()
		element.TabNext:close()
		element.TabPosition:close()
		element.TabPrevious:close()
		element.TabRight:close()
		element.Tabs:close()
		element.TabLeft:close()
		element.Subtitle:close()
		element.ComponentVersions:close()
		element.Title:close()
		if element.Shade ~= nil then
			element.Shade:close()
		end
		element.Background:close()
		Engine.UnsubscribeAndFreeModel( Engine.GetModel( Engine.GetModelForController( controller ), menuName .. ".buttonPrompts" ) )
	end )
	return self
end

