	return Z.CreateMenu( controller, "ZShareSettings" )
end

-- The second way in, and the pause-menu entry that opens it. Asked for here,
-- after everything above exists, because that file builds on it.
require( "zshareingamesettings" )

-- ------------------------------------------------------------------------

-- The lobby button and the save file belong to the frontend. The page itself
-- does not, and is built above whatever this is: core_mod loads in every
-- mode, and T7x can keep a module across the step into a match, so a menu
-- defined only in the frontend would be one the pause menu could not open.
if Engine.GetCurrentMap() == "core_frontend" then
	Z.Hook()
	if LUI.roots ~= nil and LUI.roots.UIRootFull ~= nil then
		Z.Wait( LUI.roots.UIRootFull, 0 )
	end
end

-- And the keeper, which runs wherever this file was read -- frontend or
-- match, packaged mod or loose ui_scripts, settings row of ours or somebody
-- else's. Gated on any of those, a setting changed from the pause menu looks
-- right for the rest of the session and is gone after a restart.
--
-- Not disposable, so it resets itself rather than leaving a new element
-- behind on every pass; once everything is read and written it costs a table
-- lookup.
if LUI.roots ~= nil and LUI.roots.UIRootFull ~= nil and not CoD.ZShareStorageKeeping then
	CoD.ZShareStorageKeeping = true
	LUI.roots.UIRootFull:addElement( LUI.UITimer.newElementTimer( 5000, false, function ()
		Z.Keeper()
	end ) )
end
